std/aes.mw:
@no_main

@import("raw.mw")
@import("heap.mw")
@import("hash.mw")
@import("chacha.mw")

// AES-128 and the AES-128-GCM AEAD (NIST SP 800-38D).  Table-driven software
// implementation (S-box built at first use); keys are 16 bytes, nonces 12
// bytes, tags 16 bytes.  Like any table-based AES it is not constant time
// with respect to cache timing.

var AES_SBOX: *u8 = null;

@trusted fn aes_init() {
    if AES_SBOX != null { ret; }
    var sb: *u8 = heap_alloc(256);
    var p: i64 = 1;
    var q: i64 = 1;
    var first: bool = true;
    while first || p != 1 {
        first = false;
        // p *= 3
        var hi: i64 = 0;
        if (p & 128) != 0 { hi = 27; }
        p = (p ^ ((p << 1) & 255) ^ hi) & 255;
        // q /= 3
        q = (q ^ (q << 1)) & 255;
        q = (q ^ (q << 2)) & 255;
        q = (q ^ (q << 4)) & 255;
        if (q & 128) != 0 { q = q ^ 9; }
        var x: i64 = q ^ (((q << 1) | (q >> 7)) & 255) ^ (((q << 2) | (q >> 6)) & 255) ^ (((q << 3) | (q >> 5)) & 255) ^ (((q << 4) | (q >> 4)) & 255);
        sb[p] = cast(u8) (x ^ 99);
    }
    sb[0] = 99;
    AES_SBOX = sb;
}

fn aes_xtime(x: i64) -> i64 {
    var r: i64 = (x << 1) & 255;
    if (x & 128) != 0 { r = r ^ 27; }
    ret r;
}

// Expands a 16-byte key into 176 bytes of round keys.
@trusted fn aes128_expand(key: *u8, rk: *u8) {
    aes_init();
    raw_copy(rk, key, 16);
    var rcon: i64 = 1;
    var i: i64 = 4;
    while i < 44 {
        var t0: i64 = cast(i64) rk[(i - 1) * 4];
        var t1: i64 = cast(i64) rk[(i - 1) * 4 + 1];
        var t2: i64 = cast(i64) rk[(i - 1) * 4 + 2];
        var t3: i64 = cast(i64) rk[(i - 1) * 4 + 3];
        if i % 4 == 0 {
            var tmp: i64 = t0;
            t0 = (cast(i64) AES_SBOX[t1]) ^ rcon;
            t1 = cast(i64) AES_SBOX[t2];
            t2 = cast(i64) AES_SBOX[t3];
            t3 = cast(i64) AES_SBOX[tmp];
            rcon = aes_xtime(rcon);
        }
        rk[i * 4] = rk[(i - 4) * 4] ^ cast(u8) t0;
        rk[i * 4 + 1] = rk[(i - 4) * 4 + 1] ^ cast(u8) t1;
        rk[i * 4 + 2] = rk[(i - 4) * 4 + 2] ^ cast(u8) t2;
        rk[i * 4 + 3] = rk[(i - 4) * 4 + 3] ^ cast(u8) t3;
        i = i + 1;
    }
}

@trusted fn aes_add_round_key(s: *u8, rk: *u8) {
    var i: i64 = 0;
    while i < 16 { s[i] = s[i] ^ rk[i]; i = i + 1; }
}

@trusted fn aes_sub_shift(s: *u8, t: *u8) {
    // SubBytes + ShiftRows (state is column-major: index = 4 * col + row)
    var c: i64 = 0;
    while c < 4 {
        var r: i64 = 0;
        while r < 4 {
            t[4 * c + r] = AES_SBOX[cast(i64) s[4 * ((c + r) % 4) + r]];
            r = r + 1;
        }
        c = c + 1;
    }
    raw_copy(s, t, 16);
}

@trusted fn aes_mix_columns(s: *u8) {
    var c: i64 = 0;
    while c < 4 {
        var a0: i64 = cast(i64) s[4 * c];
        var a1: i64 = cast(i64) s[4 * c + 1];
        var a2: i64 = cast(i64) s[4 * c + 2];
        var a3: i64 = cast(i64) s[4 * c + 3];
        s[4 * c] = cast(u8) (aes_xtime(a0) ^ (aes_xtime(a1) ^ a1) ^ a2 ^ a3);
        s[4 * c + 1] = cast(u8) (a0 ^ aes_xtime(a1) ^ (aes_xtime(a2) ^ a2) ^ a3);
        s[4 * c + 2] = cast(u8) (a0 ^ a1 ^ aes_xtime(a2) ^ (aes_xtime(a3) ^ a3));
        s[4 * c + 3] = cast(u8) ((aes_xtime(a0) ^ a0) ^ a1 ^ a2 ^ aes_xtime(a3));
        c = c + 1;
    }
}

@trusted fn aes128_encrypt_block(rk: *u8, in: *u8, out: *u8) {
    var s: *u8 = heap_alloc(32);
    var t: *u8 = s + 16;
    raw_copy(s, in, 16);
    aes_add_round_key(s, rk);
    var r: i64 = 1;
    while r < 10 {
        aes_sub_shift(s, t);
        aes_mix_columns(s);
        aes_add_round_key(s, rk + r * 16);
        r = r + 1;
    }
    aes_sub_shift(s, t);
    aes_add_round_key(s, rk + 160);
    raw_copy(out, s, 16);
    heap_free(s);
}

// ---------------------------------------------------------------- GCM

// y = (y xor block) * h in GF(2^128); y and h are 16 bytes, big-endian bit order.
@trusted fn ghash_mul(y: *u8, h: *u8) {
    var xh: u64 = load_be64(y);
    var xl: u64 = load_be64(y + 8);
    var vh: u64 = load_be64(h);
    var vl: u64 = load_be64(h + 8);
    var zh: u64 = 0;
    var zl: u64 = 0;
    var i: i64 = 0;
    while i < 128 {
        var bit: u64 = 0;
        if i < 64 { bit = (xh >> (cast(u64) (63 - i))) & 1; }
        else { bit = (xl >> (cast(u64) (127 - i))) & 1; }
        if bit == 1 { zh = zh ^ vh; zl = zl ^ vl; }
        var lsb: u64 = vl & 1;
        vl = (vl >> 1) | (vh << 63);
        vh = vh >> 1;
        if lsb == 1 { vh = vh ^ 0xe100000000000000; }
        i = i + 1;
    }
    store_be64(y, zh);
    store_be64(y + 8, zl);
}

@trusted fn ghash_update(y: *u8, h: *u8, data: *u8, n: i64) {
    var off: i64 = 0;
    while off < n {
        var m: i64 = n - off;
        if m > 16 { m = 16; }
        var i: i64 = 0;
        while i < m { y[i] = y[i] ^ data[off + i]; i = i + 1; }
        ghash_mul(y, h);
        off = off + m;
    }
}

@trusted fn gcm_inc32(ctr: *u8) {
    var i: i64 = 15;
    var carry: bool = true;
    while i >= 12 && carry {
        ctr[i] = ctr[i] + 1;
        carry = ctr[i] == 0;
        i = i - 1;
    }
}

@trusted fn gcm_ctr_xor(rk: *u8, ctr: *u8, in: *u8, out: *u8, n: i64) {
    var ks: *u8 = heap_alloc(16);
    var off: i64 = 0;
    while off < n {
        gcm_inc32(ctr);
        aes128_encrypt_block(rk, ctr, ks);
        var m: i64 = n - off;
        if m > 16 { m = 16; }
        var i: i64 = 0;
        while i < m { out[off + i] = in[off + i] ^ ks[i]; i = i + 1; }
        off = off + m;
    }
    heap_free(ks);
}

@trusted fn gcm_tag(rk: *u8, h: *u8, j0: *u8, aad: *u8, aadlen: i64, ct: *u8, ctlen: i64, tag: *u8) {
    var y: *u8 = heap_alloc(16);
    raw_zero(y, 16);
    ghash_update(y, h, aad, aadlen);
    ghash_update(y, h, ct, ctlen);
    var lens: *u8 = heap_alloc(16);
    store_be64(lens, (cast(u64) aadlen) << 3);
    store_be64(lens + 8, (cast(u64) ctlen) << 3);
    ghash_update(y, h, lens, 16);
    var ej: *u8 = heap_alloc(16);
    aes128_encrypt_block(rk, j0, ej);
    var i: i64 = 0;
    while i < 16 { tag[i] = y[i] ^ ej[i]; i = i + 1; }
    heap_free(y); heap_free(lens); heap_free(ej);
}

// Writes ciphertext followed by the 16-byte tag; returns len + 16.
@trusted fn aes128gcm_seal(key: *u8, nonce: *u8, aad: *u8, aadlen: i64, pt: *u8, len: i64, out: *u8) -> i64 {
    var rk: *u8 = heap_alloc(176);
    aes128_expand(key, rk);
    var h: *u8 = heap_alloc(16);
    var zero: *u8 = heap_alloc(16);
    raw_zero(zero, 16);
    aes128_encrypt_block(rk, zero, h);
    var j0: *u8 = heap_alloc(16);
    raw_copy(j0, nonce, 12);
    j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;
    var ctr: *u8 = heap_alloc(16);
    raw_copy(ctr, j0, 16);
    gcm_ctr_xor(rk, ctr, pt, out, len);
    gcm_tag(rk, h, j0, aad, aadlen, out, len, out + len);
    heap_free(rk); heap_free(h); heap_free(zero); heap_free(j0); heap_free(ctr);
    ret len + 16;
}

// `ct` is ciphertext||tag (len bytes in total).  Returns the plaintext length
// or -1 if authentication fails (nothing is written to `out` then).
@trusted fn aes128gcm_open(key: *u8, nonce: *u8, aad: *u8, aadlen: i64, ct: *u8, len: i64, out: *u8) -> i64 {
    if len < 16 { ret -1; }
    var n: i64 = len - 16;
    var rk: *u8 = heap_alloc(176);
    aes128_expand(key, rk);
    var h: *u8 = heap_alloc(16);
    var zero: *u8 = heap_alloc(16);
    raw_zero(zero, 16);
    aes128_encrypt_block(rk, zero, h);
    var j0: *u8 = heap_alloc(16);
    raw_copy(j0, nonce, 12);
    j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;
    var tag: *u8 = heap_alloc(16);
    gcm_tag(rk, h, j0, aad, aadlen, ct, n, tag);
    var ok: bool = ct_equal(tag, ct + n, 16);
    var res: i64 = -1;
    if ok {
        var ctr: *u8 = heap_alloc(16);
        raw_copy(ctr, j0, 16);
        gcm_ctr_xor(rk, ctr, ct, out, n);
        heap_free(ctr);
        res = n;
    }
    heap_free(rk); heap_free(h); heap_free(zero); heap_free(j0); heap_free(tag);
    ret res;
}

std/asn1.mw:
@no_main

// Minimal strict DER reader.  All functions work on (pointer, length) windows
// and never read outside them.

var ASN1_BOOLEAN: i64 = 1;
var ASN1_INTEGER: i64 = 2;
var ASN1_BIT_STRING: i64 = 3;
var ASN1_OCTET_STRING: i64 = 4;
var ASN1_NULL: i64 = 5;
var ASN1_OID: i64 = 6;
var ASN1_UTF8: i64 = 12;
var ASN1_PRINTABLE: i64 = 19;
var ASN1_IA5: i64 = 22;
var ASN1_UTCTIME: i64 = 23;
var ASN1_GENTIME: i64 = 24;
var ASN1_SEQUENCE: i64 = 48;
var ASN1_SET: i64 = 49;

// Parses the TLV header at `p`.  On success stores the tag byte, the header
// size and the content length, and guarantees hdr + len <= avail.
// Only single-byte tags and definite, minimally-encoded lengths are accepted.
@trusted fn der_tlv(p: *u8, avail: i64, tag: *i64, hdr: *i64, len: *i64) -> bool {
    if avail < 2 { ret false; }
    var t: i64 = cast(i64) p[0];
    if (t & 31) == 31 { ret false; }
    var l: i64 = cast(i64) p[1];
    var h: i64 = 2;
    if l >= 128 {
        var nb: i64 = l & 127;
        if nb == 0 || nb > 4 || avail < 2 + nb { ret false; }
        l = 0;
        var i: i64 = 0;
        while i < nb { l = (l << 8) | (cast(i64) p[2 + i]); i = i + 1; }
        if (cast(i64) p[2]) == 0 { ret false; }
        if l < 128 { ret false; }
        h = 2 + nb;
    }
    if l > avail - h { ret false; }
    *tag = t;
    *hdr = h;
    *len = l;
    ret true;
}

// Cursor over a window: `pos` is the offset of the next element.
struct Der {
    p: *u8;
    len: i64;
    pos: i64;
}

fn der_init(d: *Der, p: *u8, len: i64) {
    d.p = p;
    d.len = len;
    d.pos = 0;
}

fn der_done(d: *Der) -> bool { ret d.pos >= d.len; }

// Reads the next element and checks its tag.  On success `*val`/`*vlen` point
// at the content and the cursor advances past it.
@trusted fn der_next(d: *Der, want: i64, val: *rawptr, vlen: *i64) -> bool {
    var tag: i64 = 0;
    var hdr: i64 = 0;
    var len: i64 = 0;
    if !der_tlv(d.p + d.pos, d.len - d.pos, raw tag, raw hdr, raw len) { ret false; }
    if tag != want { ret false; }
    *val = d.p + d.pos + hdr;
    *vlen = len;
    d.pos = d.pos + hdr + len;
    ret true;
}

// Like der_next but returns the whole TLV (header included) via `*all`/`*alen`,
// and the tag via `*tag`, for any tag.
@trusted fn der_next_any(d: *Der, tag: *i64, val: *rawptr, vlen: *i64, all: *rawptr, alen: *i64) -> bool {
    var hdr: i64 = 0;
    var len: i64 = 0;
    if !der_tlv(d.p + d.pos, d.len - d.pos, tag, raw hdr, raw len) { ret false; }
    *all = d.p + d.pos;
    *alen = hdr + len;
    *val = d.p + d.pos + hdr;
    *vlen = len;
    d.pos = d.pos + hdr + len;
    ret true;
}

// Peeks the tag of the next element (-1 at the end or on malformed input).
@trusted fn der_peek(d: *Der) -> i64 {
    var tag: i64 = 0;
    var hdr: i64 = 0;
    var len: i64 = 0;
    if d.pos >= d.len { ret -1; }
    if !der_tlv(d.p + d.pos, d.len - d.pos, raw tag, raw hdr, raw len) { ret -1; }
    ret tag;
}

// An INTEGER's magnitude without its sign-padding zero byte.
@trusted fn der_uint(val: *u8, vlen: i64, out: *rawptr, outlen: *i64) -> bool {
    if vlen < 1 { ret false; }
    if (val[0] & 128) != 0 { ret false; }
    var p: *u8 = val;
    var n: i64 = vlen;
    if n > 1 && val[0] == 0 { p = val + 1; n = n - 1; }
    *out = p;
    *outlen = n;
    ret true;
}

// Compares an OID's DER content against raw bytes.
@trusted fn der_oid_is(val: *u8, vlen: i64, want: *u8, wlen: i64) -> bool {
    if vlen != wlen { ret false; }
    var i: i64 = 0;
    while i < vlen { if val[i] != want[i] { ret false; } i = i + 1; }
    ret true;
}

std/bigint.mw:
@no_main

@import("raw.mw")
@import("heap.mw")

// Arbitrary-precision unsigned integers (little-endian 32-bit limbs) with the
// modular arithmetic needed for RSA and elliptic curves.  Every function that
// returns a *Big returns a fresh value the caller releases with big_free.
// Reduction is shift-and-subtract: simple and constant-memory, adequate for
// signature *verification* (public data); it is not constant time.

@drop(big_release)
struct Big {
    d: *u32;
    n: i64;
}

@trusted fn big_alloc(n: i64) -> ^Big {
    var b: ^Big = cast(^Big) heap_alloc(16);
    var cap: i64 = n;
    if cap < 1 { cap = 1; }
    b.d = cast(*u32) heap_alloc_zeroed(cap * 4);
    b.n = n;
    ret b;
}

@trusted fn big_release(b: &mut Big) {
    heap_free(b.d);
}

fn big_free(b: ^Big) { }

// Frees a value that is only known by a plain pointer: the caller was its owner.
@unsafe fn big_destroy(b: *Big) { big_free(cast(^Big) b); }

@trusted fn big_trim(b: *Big) {
    while b.n > 0 && b.d[b.n - 1] == 0 { b.n = b.n - 1; }
}

@trusted fn big_from_u64(v: u64) -> ^Big {
    var b: ^Big = big_alloc(2);
    b.d[0] = cast(u32) v;
    b.d[1] = cast(u32) (v >> 32);
    big_trim(b);
    ret b;
}

@trusted fn big_copy(a: *Big) -> ^Big {
    var b: ^Big = big_alloc(a.n);
    var i: i64 = 0;
    while i < a.n { b.d[i] = a.d[i]; i = i + 1; }
    ret b;
}

@trusted fn big_from_bytes(p: *u8, len: i64) -> ^Big {
    var b: ^Big = big_alloc((len + 3) / 4);
    var i: i64 = 0;
    while i < len {
        var byte: u32 = cast(u32) p[len - 1 - i];
        var limb: i64 = i / 4;
        b.d[limb] = b.d[limb] | (byte << (cast(u32) ((i % 4) * 8)));
        i = i + 1;
    }
    big_trim(b);
    ret b;
}

// Writes `a` big-endian, left-padded with zeros to exactly `len` bytes.
// Returns false if it does not fit.
@trusted fn big_to_bytes(a: *Big, out: *u8, len: i64) -> bool {
    var i: i64 = 0;
    while i < len {
        var limb: i64 = i / 4;
        var v: u32 = 0;
        if limb < a.n { v = (a.d[limb] >> (cast(u32) ((i % 4) * 8))) & 255; }
        out[len - 1 - i] = cast(u8) v;
        i = i + 1;
    }
    while i < a.n * 4 {
        if ((a.d[i / 4] >> (cast(u32) ((i % 4) * 8))) & 255) != 0 { ret false; }
        i = i + 1;
    }
    ret true;
}

@trusted fn big_is_zero(a: *Big) -> bool {
    var i: i64 = 0;
    while i < a.n { if a.d[i] != 0 { ret false; } i = i + 1; }
    ret true;
}

@trusted fn big_bits(a: *Big) -> i64 {
    var n: i64 = a.n;
    while n > 0 && a.d[n - 1] == 0 { n = n - 1; }
    if n == 0 { ret 0; }
    var top: u32 = a.d[n - 1];
    var bits: i64 = 0;
    while top != 0 { bits = bits + 1; top = top >> 1; }
    ret (n - 1) * 32 + bits;
}

@trusted fn big_bit(a: *Big, i: i64) -> i64 {
    var limb: i64 = i / 32;
    if limb >= a.n { ret 0; }
    ret cast(i64) ((a.d[limb] >> (cast(u32) (i % 32))) & 1);
}

@trusted fn big_is_odd(a: *Big) -> bool {
    if a.n == 0 { ret false; }
    ret (a.d[0] & 1) == 1;
}

@trusted fn big_cmp(a: *Big, b: *Big) -> i64 {
    var n: i64 = a.n;
    if b.n > n { n = b.n; }
    var i: i64 = n - 1;
    while i >= 0 {
        var x: u32 = 0;
        var y: u32 = 0;
        if i < a.n { x = a.d[i]; }
        if i < b.n { y = b.d[i]; }
        if x > y { ret 1; }
        if x < y { ret -1; }
        i = i - 1;
    }
    ret 0;
}

@trusted fn big_add(a: *Big, b: *Big) -> ^Big {
    var n: i64 = a.n;
    if b.n > n { n = b.n; }
    var r: ^Big = big_alloc(n + 1);
    var carry: u64 = 0;
    var i: i64 = 0;
    while i < n {
        var x: u64 = 0;
        var y: u64 = 0;
        if i < a.n { x = cast(u64) a.d[i]; }
        if i < b.n { y = cast(u64) b.d[i]; }
        var s: u64 = x + y + carry;
        r.d[i] = cast(u32) s;
        carry = s >> 32;
        i = i + 1;
    }
    r.d[n] = cast(u32) carry;
    big_trim(r);
    ret r;
}

// a - b, requires a >= b.
@trusted fn big_sub(a: *Big, b: *Big) -> ^Big {
    var r: ^Big = big_alloc(a.n);
    var borrow: u64 = 0;
    var i: i64 = 0;
    while i < a.n {
        var x: u64 = cast(u64) a.d[i];
        var y: u64 = borrow;
        if i < b.n { y = y + (cast(u64) b.d[i]); }
        if x >= y { r.d[i] = cast(u32) (x - y); borrow = 0; }
        else { r.d[i] = cast(u32) ((x + 4294967296) - y); borrow = 1; }
        i = i + 1;
    }
    big_trim(r);
    ret r;
}

@trusted fn big_mul(a: *Big, b: *Big) -> ^Big {
    var r: ^Big = big_alloc(a.n + b.n);
    var i: i64 = 0;
    while i < a.n {
        var carry: u64 = 0;
        var x: u64 = cast(u64) a.d[i];
        var j: i64 = 0;
        while j < b.n {
            var t: u64 = x * (cast(u64) b.d[j]) + (cast(u64) r.d[i + j]) + carry;
            r.d[i + j] = cast(u32) t;
            carry = t >> 32;
            j = j + 1;
        }
        r.d[i + b.n] = cast(u32) carry;
        i = i + 1;
    }
    big_trim(r);
    ret r;
}

// a mod m (m > 0).
@trusted fn big_mod(a: *Big, m: *Big) -> ^Big {
    var r: ^Big = big_alloc(m.n + 1);
    var bits: i64 = big_bits(a);
    var i: i64 = bits - 1;
    while i >= 0 {
        // r = r * 2 + bit
        var carry: u32 = cast(u32) big_bit(a, i);
        var k: i64 = 0;
        while k < r.n {
            var v: u32 = r.d[k];
            r.d[k] = (v << 1) | carry;
            carry = v >> 31;
            k = k + 1;
        }
        if big_cmp(r, m) >= 0 {
            var borrow: u64 = 0;
            k = 0;
            while k < r.n {
                var x: u64 = cast(u64) r.d[k];
                var y: u64 = borrow;
                if k < m.n { y = y + (cast(u64) m.d[k]); }
                if x >= y { r.d[k] = cast(u32) (x - y); borrow = 0; }
                else { r.d[k] = cast(u32) ((x + 4294967296) - y); borrow = 1; }
                k = k + 1;
            }
        }
        i = i - 1;
    }
    big_trim(r);
    ret r;
}

fn big_modmul(a: *Big, b: *Big, m: *Big) -> ^Big {
    var p: ^Big = big_mul(a, b);
    var r: ^Big = big_mod(p, m);
    big_free(p);
    ret r;
}

fn big_modadd(a: *Big, b: *Big, m: *Big) -> ^Big {
    var s: ^Big = big_add(a, b);
    var r: ^Big = big_mod(s, m);
    big_free(s);
    ret r;
}

// (a - b) mod m for a, b < m.
fn big_modsub(a: *Big, b: *Big, m: *Big) -> ^Big {
    if big_cmp(a, b) >= 0 { ret big_sub(a, b); }
    var t: ^Big = big_add(a, m);
    var r: ^Big = big_sub(t, b);
    big_free(t);
    ret r;
}

fn big_modexp(base: *Big, exp: *Big, m: *Big) -> ^Big {
    var b: ^Big = big_mod(base, m);
    var result: ^Big = big_from_u64(1);
    var one: ^Big = big_from_u64(1);
    if big_cmp(m, one) == 0 { big_free(result); big_free(b); big_free(one); ret big_alloc(0); }
    big_free(one);
    var i: i64 = big_bits(exp) - 1;
    while i >= 0 {
        var sq: ^Big = big_modmul(result, result, m);
        big_free(result);
        result = sq;
        if big_bit(exp, i) == 1 {
            var ml: ^Big = big_modmul(result, b, m);
            big_free(result);
            result = ml;
        }
        i = i - 1;
    }
    big_free(b);
    ret result;
}

// a^-1 mod p for prime p (Fermat).
fn big_modinv_prime(a: *Big, p: *Big) -> ^Big {
    var two: ^Big = big_from_u64(2);
    var e: ^Big = big_sub(p, two);
    var r: ^Big = big_modexp(a, e, p);
    big_free(two); big_free(e);
    ret r;
}

