@no_main

@import("raw.mw")
@import("heap.mw")
@import("bigint.mw")
@import("asn1.mw")
@import("encoding.mw")

// ECDSA signature verification over NIST P-256 and P-384 (FIPS 186-4), with
// Jacobian-coordinate arithmetic and Shamir's trick.  Verification only: all
// inputs are public, so the variable-time bigint code is acceptable.

var ECC_P256: i64 = 1;
var ECC_P384: i64 = 2;

@drop(curve_release)
struct Curve {
    p: *Big;
    n: *Big;
    b: *Big;
    gx: *Big;
    gy: *Big;
    nbytes: i64;
}

// Jacobian point; the point at infinity has z == 0.
@drop(jp_release)
struct JP {
    x: *Big;
    y: *Big;
    z: *Big;
}

// ---- temporaries: every pooled Big is released in one go ----
var EC_POOL: i64 = 0;
var EC_POOL_N: i64 = 0;
var EC_POOL_CAP: i64 = 0;

@trusted fn pl(b: *Big) -> *Big {
    if EC_POOL_N == EC_POOL_CAP {
        var ncap: i64 = EC_POOL_CAP * 2;
        if ncap < 64 { ncap = 64; }
        var np: *i64 = cast(*i64) heap_alloc(ncap * 8);
        if EC_POOL_N > 0 { raw_copy(cast(*u8) np, cast(*u8) EC_POOL, EC_POOL_N * 8); heap_free(cast(*u8) EC_POOL); }
        EC_POOL = cast(i64) np;
        EC_POOL_CAP = ncap;
    }
    var arr: *i64 = cast(*i64) EC_POOL;
    arr[EC_POOL_N] = cast(i64) b;
    EC_POOL_N = EC_POOL_N + 1;
    ret b;
}

@trusted fn pool_release(mark: i64) {
    var arr: *i64 = cast(*i64) EC_POOL;
    while EC_POOL_N > mark {
        EC_POOL_N = EC_POOL_N - 1;
        big_destroy(cast(*Big) arr[EC_POOL_N]);
    }
}

fn mm(a: *Big, b: *Big, p: *Big) -> *Big { ret pl(big_modmul(a, b, p)); }
fn ma(a: *Big, b: *Big, p: *Big) -> *Big { ret pl(big_modadd(a, b, p)); }
fn ms(a: *Big, b: *Big, p: *Big) -> *Big { ret pl(big_modsub(a, b, p)); }

@trusted fn jp_new() -> ^JP {
    var j: ^JP = cast(^JP) heap_alloc(24);
    j.x = cast(*Big) big_alloc(0);
    j.y = cast(*Big) big_alloc(0);
    j.z = cast(*Big) big_alloc(0);
    ret j;
}

@trusted fn jp_release(j: &mut JP) {
    big_destroy(j.x); big_destroy(j.y); big_destroy(j.z);
}

fn jp_free(j: ^JP) { }

@trusted fn jp_set(r: *JP, x: *Big, y: *Big, z: *Big) {
    big_destroy(r.x); big_destroy(r.y); big_destroy(r.z);
    r.x = cast(*Big) big_copy(x);
    r.y = cast(*Big) big_copy(y);
    r.z = cast(*Big) big_copy(z);
}

fn jp_double(r: *JP, a: *JP, c: *Curve) {
    var p: *Big = c.p;
    if big_is_zero(a.z) || big_is_zero(a.y) {
        var zero: ^Big = big_alloc(0);
        var one: ^Big = big_from_u64(1);
        jp_set(r, one, one, zero);
        big_free(zero); big_free(one);
        ret;
    }
    var mark: i64 = EC_POOL_N;
    var delta: *Big = mm(a.z, a.z, p);
    var gamma: *Big = mm(a.y, a.y, p);
    var beta: *Big = mm(a.x, gamma, p);
    var t1: *Big = ms(a.x, delta, p);
    var t2: *Big = ma(a.x, delta, p);
    var t3: *Big = mm(t1, t2, p);
    var alpha: *Big = ma(ma(t3, t3, p), t3, p);
    var b2: *Big = ma(beta, beta, p);
    var b4: *Big = ma(b2, b2, p);
    var b8: *Big = ma(b4, b4, p);
    var x3: *Big = ms(mm(alpha, alpha, p), b8, p);
    var yz: *Big = ma(a.y, a.z, p);
    var z3: *Big = ms(ms(mm(yz, yz, p), gamma, p), delta, p);
    var g2: *Big = mm(gamma, gamma, p);
    var g2b: *Big = ma(g2, g2, p);
    var g4: *Big = ma(g2b, g2b, p);
    var g8: *Big = ma(g4, g4, p);
    var y3: *Big = ms(mm(alpha, ms(b4, x3, p), p), g8, p);
    jp_set(r, x3, y3, z3);
    pool_release(mark);
}

fn jp_add(r: *JP, a: *JP, b: *JP, c: *Curve) {
    var p: *Big = c.p;
    if big_is_zero(a.z) { jp_set(r, b.x, b.y, b.z); ret; }
    if big_is_zero(b.z) { jp_set(r, a.x, a.y, a.z); ret; }
    var mark: i64 = EC_POOL_N;
    var z1z1: *Big = mm(a.z, a.z, p);
    var z2z2: *Big = mm(b.z, b.z, p);
    var u1: *Big = mm(a.x, z2z2, p);
    var u2: *Big = mm(b.x, z1z1, p);
    var s1: *Big = mm(mm(a.y, b.z, p), z2z2, p);
    var s2: *Big = mm(mm(b.y, a.z, p), z1z1, p);
    var h: *Big = ms(u2, u1, p);
    var sd: *Big = ms(s2, s1, p);
    if big_is_zero(h) {
        var same: bool = big_is_zero(sd);
        pool_release(mark);
        if same { jp_double(r, a, c); }
        else {
            var zero: ^Big = big_alloc(0);
            var one: ^Big = big_from_u64(1);
            jp_set(r, one, one, zero);
            big_free(zero); big_free(one);
        }
        ret;
    }
    var h2: *Big = ma(h, h, p);
    var i: *Big = mm(h2, h2, p);
    var j: *Big = mm(h, i, p);
    var rr: *Big = ma(sd, sd, p);
    var v: *Big = mm(u1, i, p);
    var x3: *Big = ms(ms(mm(rr, rr, p), j, p), ma(v, v, p), p);
    var s1j: *Big = mm(s1, j, p);
    var y3: *Big = ms(mm(rr, ms(v, x3, p), p), ma(s1j, s1j, p), p);
    var zs: *Big = ma(a.z, b.z, p);
    var z3: *Big = mm(ms(ms(mm(zs, zs, p), z1z1, p), z2z2, p), h, p);
    jp_set(r, x3, y3, z3);
    pool_release(mark);
}

@trusted fn curve_new(id: i64) -> ^Curve {
    var c: ^Curve = cast(^Curve) heap_alloc(48);
    var hp: *u8 = "";
    var hn: *u8 = "";
    var hb: *u8 = "";
    var hx: *u8 = "";
    var hy: *u8 = "";
    if id == 1 {
        c.nbytes = 32;
        hp = "ffffffff00000001000000000000000000000000ffffffffffffffffffffffff";
        hn = "ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551";
        hb = "5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b";
        hx = "6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296";
        hy = "4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5";
    } else if id == 2 {
        c.nbytes = 48;
        hp = "fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeffffffff0000000000000000ffffffff";
        hn = "ffffffffffffffffffffffffffffffffffffffffffffffffc7634d81f4372ddf581a0db248b0a77aecec196accc52973";
        hb = "b3312fa7e23ee7e4988e056be3f82d19181d9c6efe8141120314088f5013875ac656398d8a2ed19d2a85c8edd3ec2aef";
        hx = "aa87ca22be8b05378eb1c71ef320ad746e1d3b628ba79b9859f741e082542a385502f25dbf55296c3a545e3872760ab7";
        hy = "3617de4a96262c6f5d9e98bf9292dc29f8f41dbd289a147ce9da3113b5f0b8c00a60b1ce1d7e819d7a431d7c90ea0e5f";
    } else {
        heap_free(c);
        ret null;
    }
    var buf: *u8 = heap_alloc(48);
    hex_decode(hp, c.nbytes * 2, buf); c.p = cast(*Big) big_from_bytes(buf, c.nbytes);
    hex_decode(hn, c.nbytes * 2, buf); c.n = cast(*Big) big_from_bytes(buf, c.nbytes);
    hex_decode(hb, c.nbytes * 2, buf); c.b = cast(*Big) big_from_bytes(buf, c.nbytes);
    hex_decode(hx, c.nbytes * 2, buf); c.gx = cast(*Big) big_from_bytes(buf, c.nbytes);
    hex_decode(hy, c.nbytes * 2, buf); c.gy = cast(*Big) big_from_bytes(buf, c.nbytes);
    heap_free(buf);
    ret c;
}

@trusted fn curve_release(c: &mut Curve) {
    big_destroy(c.p); big_destroy(c.n); big_destroy(c.b); big_destroy(c.gx); big_destroy(c.gy);
}

fn curve_free(c: ^Curve) { }

fn ec_on_curve(c: *Curve, x: *Big, y: *Big) -> bool {
    var p: *Big = c.p;
    if big_cmp(x, p) >= 0 || big_cmp(y, p) >= 0 { ret false; }
    var mark: i64 = EC_POOL_N;
    var lhs: *Big = mm(y, y, p);
    var x3: *Big = mm(mm(x, x, p), x, p);
    var three_x: *Big = ma(ma(x, x, p), x, p);
    var rhs: *Big = ma(ms(x3, three_x, p), c.b, p);
    var ok: bool = big_cmp(lhs, rhs) == 0;
    pool_release(mark);
    ret ok;
}

fn jp_affine(j: *JP, c: *Curve) -> *Big {
    var zi: ^Big = big_modinv_prime(j.z, c.p);
    var zi2: ^Big = big_modmul(zi, zi, c.p);
    var x: ^Big = big_modmul(j.x, zi2, c.p);
    big_free(zi); big_free(zi2);
    ret cast(*Big) x;
}

// Verifies (r, s) over `hash` against the uncompressed public key `pub`
// (04 || X || Y).  r and s are big-endian magnitudes.
@trusted fn ecdsa_verify(curve: i64, pub: *u8, publen: i64, hash: *u8, hlen: i64, rb: *u8, rlen: i64, sb: *u8, slen: i64) -> bool {
    var c: ^Curve = curve_new(curve);
    if c == null { ret false; }
    var nb: i64 = c.nbytes;
    var ok: bool = false;
    if publen == 1 + 2 * nb && pub[0] == 4 {
        var qx: ^Big = big_from_bytes(pub + 1, nb);
        var qy: ^Big = big_from_bytes(pub + 1 + nb, nb);
        var r: ^Big = big_from_bytes(rb, rlen);
        var s: ^Big = big_from_bytes(sb, slen);
        var zero_ok: bool = !big_is_zero(r) && !big_is_zero(s);
        if zero_ok && big_cmp(r, c.n) < 0 && big_cmp(s, c.n) < 0 && ec_on_curve(c, qx, qy) {
            var hl: i64 = hlen;
            if hl > nb { hl = nb; }
            var e0: ^Big = big_from_bytes(hash, hl);
            var e: ^Big = big_mod(e0, c.n);
            var w: ^Big = big_modinv_prime(s, c.n);
            var u1: ^Big = big_modmul(e, w, c.n);
            var u2: ^Big = big_modmul(r, w, c.n);
            var one: ^Big = big_from_u64(1);
            var g: ^JP = jp_new(); jp_set(g, c.gx, c.gy, one);
            var q: ^JP = jp_new(); jp_set(q, qx, qy, one);
            var gq: ^JP = jp_new(); jp_add(gq, g, q, c);
            var acc: ^JP = jp_new();
            var zero: ^Big = big_alloc(0);
            jp_set(acc, one, one, zero);
            var bits: i64 = nb * 8;
            var i: i64 = bits - 1;
            while i >= 0 {
                jp_double(acc, acc, c);
                var b1: i64 = big_bit(u1, i);
                var b2: i64 = big_bit(u2, i);
                if b1 == 1 && b2 == 1 { jp_add(acc, acc, gq, c); }
                else if b1 == 1 { jp_add(acc, acc, g, c); }
                else if b2 == 1 { jp_add(acc, acc, q, c); }
                i = i - 1;
            }
            if !big_is_zero(acc.z) {
                var xa: *Big = jp_affine(acc, c);
                var xr: ^Big = big_mod(xa, c.n);
                ok = big_cmp(xr, r) == 0;
                big_destroy(xa); big_free(xr);
            }
            jp_free(g); jp_free(q); jp_free(gq); jp_free(acc);
            big_free(e0); big_free(e); big_free(w); big_free(u1); big_free(u2); big_free(one); big_free(zero);
        }
        big_free(qx); big_free(qy); big_free(r); big_free(s);
    }
    curve_free(c);
    ret ok;
}

// Same, with the signature as DER SEQUENCE { INTEGER r, INTEGER s }.
@trusted fn ecdsa_verify_der(curve: i64, pub: *u8, publen: i64, hash: *u8, hlen: i64, sig: *u8, siglen: i64) -> bool {
    var outer: Der = Der { p: null, len: 0, pos: 0 };
    var body: rawptr = null;
    var blen: i64 = 0;
    der_init(raw outer, sig, siglen);
    if !der_next(raw outer, 48, raw body, raw blen) || !der_done(raw outer) { ret false; }
    var inner: Der = Der { p: null, len: 0, pos: 0 };
    der_init(raw inner, body, blen);
    var rv: rawptr = null; var rl: i64 = 0;
    var sv: rawptr = null; var sl: i64 = 0;
    if !der_next(raw inner, 2, raw rv, raw rl) || !der_next(raw inner, 2, raw sv, raw sl) || !der_done(raw inner) { ret false; }
    var rp: rawptr = null; var rpl: i64 = 0;
    var sp: rawptr = null; var spl: i64 = 0;
    if !der_uint(rv, rl, raw rp, raw rpl) || !der_uint(sv, sl, raw sp, raw spl) { ret false; }
    ret ecdsa_verify(curve, pub, publen, hash, hlen, rp, rpl, sp, spl);
}

std/encoding.mw:
@no_main

@import("heap.mw")

// Hex, Base64 (RFC 4648, standard and URL-safe) and UTF-8 helpers.
// Encoders write into a caller buffer and return the length; decoders return
// the decoded length or -1 on malformed input.  `*_len` helpers give the
// worst-case output size.

fn hex_encode_len(n: i64) -> i64 { ret n * 2; }
fn hex_decode_len(n: i64) -> i64 { ret n / 2; }

@trusted fn hex_encode(src: *u8, n: i64, out: *u8) -> i64 {
    var d: *u8 = "0123456789abcdef";
    var i: i64 = 0;
    while i < n {
        var b: i64 = cast(i64) src[i];
        out[i * 2] = d[b >> 4];
        out[i * 2 + 1] = d[b & 15];
        i = i + 1;
    }
    ret n * 2;
}

fn hex_digit(c: u8) -> i64 {
    var v: i64 = cast(i64) c;
    if v >= 48 && v <= 57 { ret v - 48; }
    if v >= 97 && v <= 102 { ret v - 87; }
    if v >= 65 && v <= 70 { ret v - 55; }
    ret -1;
}

@trusted fn hex_decode(src: *u8, n: i64, out: *u8) -> i64 {
    if n % 2 != 0 { ret -1; }
    var i: i64 = 0;
    while i < n {
        var hi: i64 = hex_digit(src[i]);
        var lo: i64 = hex_digit(src[i + 1]);
        if hi < 0 || lo < 0 { ret -1; }
        out[i / 2] = cast(u8) (hi * 16 + lo);
        i = i + 2;
    }
    ret n / 2;
}

fn base64_encode_len(n: i64) -> i64 { ret ((n + 2) / 3) * 4; }
fn base64_decode_len(n: i64) -> i64 { ret (n / 4) * 3 + 3; }

@trusted fn b64_encode_with(src: *u8, n: i64, out: *u8, alpha: *u8, pad: bool) -> i64 {
    var o: i64 = 0;
    var i: i64 = 0;
    while i + 3 <= n {
        var v: i64 = ((cast(i64) src[i]) << 16) | ((cast(i64) src[i + 1]) << 8) | (cast(i64) src[i + 2]);
        out[o] = alpha[(v >> 18) & 63];
        out[o + 1] = alpha[(v >> 12) & 63];
        out[o + 2] = alpha[(v >> 6) & 63];
        out[o + 3] = alpha[v & 63];
        o = o + 4;
        i = i + 3;
    }
    var rest: i64 = n - i;
    if rest == 1 {
        var v: i64 = (cast(i64) src[i]) << 16;
        out[o] = alpha[(v >> 18) & 63];
        out[o + 1] = alpha[(v >> 12) & 63];
        o = o + 2;
        if pad { out[o] = 61; out[o + 1] = 61; o = o + 2; }
    } else if rest == 2 {
        var v: i64 = ((cast(i64) src[i]) << 16) | ((cast(i64) src[i + 1]) << 8);
        out[o] = alpha[(v >> 18) & 63];
        out[o + 1] = alpha[(v >> 12) & 63];
        out[o + 2] = alpha[(v >> 6) & 63];
        o = o + 3;
        if pad { out[o] = 61; o = o + 1; }
    }
    ret o;
}

fn base64_encode(src: *u8, n: i64, out: *u8) -> i64 {
    ret b64_encode_with(src, n, out, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true);
}
// URL-safe alphabet, no padding (as used by JWT).
fn base64url_encode(src: *u8, n: i64, out: *u8) -> i64 {
    ret b64_encode_with(src, n, out, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_", false);
}

fn b64_val(c: u8) -> i64 {
    var v: i64 = cast(i64) c;
    if v >= 65 && v <= 90 { ret v - 65; }
    if v >= 97 && v <= 122 { ret v - 71; }
    if v >= 48 && v <= 57 { ret v + 4; }
    if v == 43 || v == 45 { ret 62; }
    if v == 47 || v == 95 { ret 63; }
    ret -1;
}

// Accepts both alphabets, optional padding, and skips ASCII whitespace
// (so PEM bodies can be decoded directly).
@trusted fn base64_decode(src: *u8, n: i64, out: *u8) -> i64 {
    var acc: i64 = 0;
    var bits: i64 = 0;
    var o: i64 = 0;
    var seen_pad: bool = false;
    var chars: i64 = 0;
    var i: i64 = 0;
    while i < n {
        var c: u8 = src[i];
        i = i + 1;
        if c == 32 || c == 10 || c == 13 || c == 9 { acc = acc; }
        else if c == 61 { seen_pad = true; }
        else {
            if seen_pad { ret -1; }
            var v: i64 = b64_val(c);
            if v < 0 { ret -1; }
            acc = ((acc << 6) | v) & 0xffffff;
            bits = bits + 6;
            chars = chars + 1;
            if bits >= 8 {
                bits = bits - 8;
                out[o] = cast(u8) ((acc >> bits) & 255);
                o = o + 1;
            }
        }
    }
    if chars % 4 == 1 { ret -1; }
    ret o;
}

// ---------------------------------------------------------------- UTF-8

// Number of bytes of the sequence starting at `s` (bounded by `n`), or 0 if
// it is not a well-formed, shortest-form, non-surrogate UTF-8 sequence.
@trusted fn utf8_seq_len(s: *u8, n: i64) -> i64 {
    if n < 1 { ret 0; }
    var c: i64 = cast(i64) s[0];
    if c < 128 { ret 1; }
    if c >= 194 && c <= 223 {
        if n < 2 || ((cast(i64) s[1]) & 192) != 128 { ret 0; }
        ret 2;
    }
    if c >= 224 && c <= 239 {
        if n < 3 { ret 0; }
        var c1: i64 = cast(i64) s[1];
        if (c1 & 192) != 128 || ((cast(i64) s[2]) & 192) != 128 { ret 0; }
        if c == 224 && c1 < 160 { ret 0; }
        if c == 237 && c1 > 159 { ret 0; }
        ret 3;
    }
    if c >= 240 && c <= 244 {
        if n < 4 { ret 0; }
        var d1: i64 = cast(i64) s[1];
        if (d1 & 192) != 128 || ((cast(i64) s[2]) & 192) != 128 || ((cast(i64) s[3]) & 192) != 128 { ret 0; }
        if c == 240 && d1 < 144 { ret 0; }
        if c == 244 && d1 > 143 { ret 0; }
        ret 4;
    }
    ret 0;
}

@trusted fn utf8_valid(s: *u8, n: i64) -> bool {
    var i: i64 = 0;
    while i < n {
        var l: i64 = utf8_seq_len(s + i, n - i);
        if l == 0 { ret false; }
        i = i + l;
    }
    ret true;
}

@trusted fn utf8_count(s: *u8, n: i64) -> i64 {
    var i: i64 = 0;
    var cnt: i64 = 0;
    while i < n {
        var l: i64 = utf8_seq_len(s + i, n - i);
        if l == 0 { ret -1; }
        i = i + l;
        cnt = cnt + 1;
    }
    ret cnt;
}

// Decodes one code point; stores its byte length in *len.  Returns -1 if malformed.
@trusted fn utf8_decode(s: *u8, n: i64, len: *i64) -> i64 {
    var l: i64 = utf8_seq_len(s, n);
    *len = l;
    if l == 0 { ret -1; }
    var c: i64 = cast(i64) s[0];
    if l == 1 { ret c; }
    if l == 2 { ret ((c & 31) << 6) | ((cast(i64) s[1]) & 63); }
    if l == 3 { ret ((c & 15) << 12) | (((cast(i64) s[1]) & 63) << 6) | ((cast(i64) s[2]) & 63); }
    ret ((c & 7) << 18) | (((cast(i64) s[1]) & 63) << 12) | (((cast(i64) s[2]) & 63) << 6) | ((cast(i64) s[3]) & 63);
}

// Encodes a code point into `out` (up to 4 bytes); returns the length, 0 if invalid.
@trusted fn utf8_encode(cp: i64, out: *u8) -> i64 {
    if cp < 0 || cp > 1114111 || (cp >= 55296 && cp <= 57343) { ret 0; }
    if cp < 128 { out[0] = cast(u8) cp; ret 1; }
    if cp < 2048 { out[0] = cast(u8) (192 | (cp >> 6)); out[1] = cast(u8) (128 | (cp & 63)); ret 2; }
    if cp < 65536 {
        out[0] = cast(u8) (224 | (cp >> 12));
        out[1] = cast(u8) (128 | ((cp >> 6) & 63));
        out[2] = cast(u8) (128 | (cp & 63));
        ret 3;
    }
    out[0] = cast(u8) (240 | (cp >> 18));
    out[1] = cast(u8) (128 | ((cp >> 12) & 63));
    out[2] = cast(u8) (128 | ((cp >> 6) & 63));
    out[3] = cast(u8) (128 | (cp & 63));
    ret 4;
}

std/env.mw:
@no_main

@import("text.mw")
@import("os.mw")

// Command-line arguments and environment variables.  Call env_init from main
// first:
//
//     @export fn main(argc: i32, argv: rawptr) -> i32 {
//         env_init(argc, argv);
//         ... arg_get(1) ... env_get("HOME") ...
//
// The environment block is read from the stack layout every System V style
// entry point provides (envp follows argv), so this works on Linux and macOS
// without libc.  On Windows it is built from GetEnvironmentStringsA.

var ENV_ARGC: i64 = 0;
var ENV_ARGV: i64 = 0;
var ENV_OK: i64 = 0;

fn env_init(argc: i32, argv: rawptr) {
    ENV_ARGC = cast(i64) argc;
    ENV_ARGV = cast(i64) argv;
    ENV_OK = 1;
    SYS_ENVP = cast(i64) env_block();
}

fn arg_count() -> i64 { ret ENV_ARGC; }

// The i-th argument (0 is the program name), or null when out of range.
@trusted fn arg_get(i: i64) -> *u8 {
    if ENV_OK == 0 || i < 0 || i >= ENV_ARGC { ret null; }
    var a: *i64 = cast(*i64) ENV_ARGV;
    ret cast(*u8) a[i];
}

var ENV_BLOCK: i64 = 0;

// The platform layer knows where the environment lives (sys_env_block): right
// after argv on Linux and macOS, a block built from the process environment
// on Windows (the C runtime does not put envp next to argv there).
@trusted fn env_block() -> *i64 {
    if ENV_OK == 0 { ret null; }
    if ENV_BLOCK == 0 { ENV_BLOCK = cast(i64) sys_env_block(ENV_ARGC, ENV_ARGV); }
    ret cast(*i64) ENV_BLOCK;
}

// Number of "NAME=value" entries.
@trusted fn env_count() -> i64 {
    var e: *i64 = env_block();
    if e == null { ret 0; }
    var n: i64 = 0;
    while e[n] != 0 { n = n + 1; }
    ret n;
}

// The i-th "NAME=value" entry, or null.
@trusted fn env_at(i: i64) -> *u8 {
    if i < 0 || i >= env_count() { ret null; }
    var e: *i64 = env_block();
    ret cast(*u8) e[i];
}

// Value of the variable (a pointer into the environment block), or null.
@trusted fn env_get(name: *u8) -> *u8 {
    var nl: i64 = 0;
    while name[nl] != 0 { nl = nl + 1; }
    var e: *i64 = env_block();
    if e == null || nl == 0 { ret null; }
    var i: i64 = 0;
    while e[i] != 0 {
        var entry: *u8 = cast(*u8) e[i];
        var k: i64 = 0;
        while k < nl && entry[k] == name[k] { k = k + 1; }
        if k == nl && entry[nl] == 61 { ret entry + nl + 1; }
        i = i + 1;
    }
    ret null;
}

// Like env_get but returns `fallback` when the variable is not set.
fn env_get_or(name: *u8, fallback: *u8) -> *u8 {
    var v: *u8 = env_get(name);
    if v == null { ret fallback; }
    ret v;
}

