        var s1: u32 = rotr32(b, 17) ^ rotr32(b, 19) ^ (b >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        i = i + 1;
    }
    var a: u32 = h[0];
    var b: u32 = h[1];
    var c: u32 = h[2];
    var d: u32 = h[3];
    var e: u32 = h[4];
    var f: u32 = h[5];
    var g: u32 = h[6];
    var hh: u32 = h[7];
    i = 0;
    while i < 64 {
