// Frees a message: it takes the owner, which is dropped here.
fn http_message_free(m: ^HttpMessage) { }

@unsafe fn http_message_destroy(m: *HttpMessage) { http_message_free(cast(^HttpMessage) m); }

fn http_header_add(m: *HttpMessage, name: *u8, value: *u8) {
    vec_ptr_push(m.headers, str_dup(name));
    vec_ptr_push(m.headers, str_dup(value));
}

// First header called `name` (case-insensitive), or null.
fn http_header_get(m: *HttpMessage, name: *u8) -> *u8 {
    var i: i64 = 0;
    while i + 1 < m.headers.len {
        var n: *u8 = cast(*u8) vec_ptr_get(m.headers, i);
        if str_eq_nocase(n, name) {
            ret cast(*u8) vec_ptr_get(m.headers, i + 1);
        }
        i = i + 2;
    }
    ret null;
}

@trusted fn http_header_has_token(m: *HttpMessage, name: *u8, token: *u8) -> bool {
    var v: *u8 = http_header_get(m, name);
    if v == null {
        ret false;
    }
    var parts: ^VecPtr = str_split(v, 44);
    var found: bool = false;
    var i: i64 = 0;
    while i < parts.len {
        var p: *u8 = cast(*u8) vec_ptr_get(parts, i);
        var t: *u8 = str_trim(p);
        if str_eq_nocase(t, token) {
            found = true;
        }
        dealloc(t);
        dealloc(p);
        i = i + 1;
    }
    vec_ptr_free(parts);
    ret found;
}

@trusted fn http_set_body(m: *HttpMessage, data: *u8, len: i64) {
    dealloc(m.body);
    m.body = alloc(len + 1);
    mem_copy(m.body, data, len);
    m.body[len] = 0;
    m.body_len = len;
}

// Reads "Name: value" lines until the blank line.
@trusted fn http_read_headers(c: *HttpConn, m: *HttpMessage) -> bool {
    var line: ^String = string_new(256);
    var count: i64 = 0;
    var ok: bool = true;
    while ok {
        if !http_conn_read_line(c, line, 16384) {
            ok = false;
        } else {
            if line.len == 0 {
                string_free(line);
