struct LinearMapEntry {
    key: *String;
    value: rawptr;
}

@drop(linear_map_release)
struct LinearMap {
    entries: ^VecPtr; // Stocke des *LinearMapEntry
}

@trusted fn linear_map_new(initial_cap: i64) -> ^LinearMap {
    var map: ^LinearMap = cast(^LinearMap) alloc(24);
    map.entries = vec_ptr_new(initial_cap);
    ret map;
}

@trusted fn linear_map_put(map: *LinearMap, key: *String, value: rawptr) {
    if (map == 0 || key == 0) { ret; }

    var entry: *LinearMapEntry = alloc(16);
    entry.key = key;
    entry.value = value;

    vec_ptr_push(map.entries, entry);
}

@trusted fn linear_map_get(map: *LinearMap, key: *String) -> rawptr {
    if (map == 0 || key == 0) { ret 0; }

    var len: i64 = map.entries.len;
    var i: i64 = len - 1;

    while (i >= 0) {
        var entry: *LinearMapEntry = cast(*LinearMapEntry) vec_ptr_get(map.entries, i);
        if (entry != 0 && entry.key != 0) {
            if (string_eq(entry.key, key) == 1) {
                ret entry.value;
            }
        }
        i = i - 1;
    }

    ret 0;
}

// Run by the drop: frees the entries; `entries` (an owner) and the map itself are freed after it.
@trusted fn linear_map_release(map: &mut LinearMap) {
    var i: i64 = 0;
    while (i < map.entries.len) {
        var entry: *LinearMapEntry = cast(*LinearMapEntry) vec_ptr_get(map.entries, i);
        if (entry != 0) {
            dealloc(entry);
        }
        i = i + 1;
    }
}

// Frees a map (not the keys and values): it takes the owner, which is dropped here.
fn linear_map_free(map: ^LinearMap) { }

// Frees a map that is only known by a plain pointer: the caller was its owner.
@unsafe fn linear_map_destroy(map: *LinearMap) { linear_map_free(cast(^LinearMap) map); }

struct HashNode {
    key: *String;
    value: rawptr;
    hash: i64;
    next: *HashNode;
}

@drop(hash_map_release)
struct HashMap {
    buckets: ^VecPtr;
    capacity: i64;
    count: i64;
}

@trusted fn hash_djb2(s: *String) -> i64 {
    if (s == 0 || s.data == 0) { ret 0; }

    var hash: i64 = 5381;
    var i: i64 = 0;
    var ptr: *u8 = s.data;

    while (i < s.len) {
        var c: u8 = *ptr;
        hash = (hash * 32 + hash) + cast(i64) c;
        ptr = ptr + 1;
        i = i + 1;
    }

    if (hash < 0) {
        ret -hash;
    }
    ret hash;
}

@trusted fn hash_map_new(capacity: i64) -> ^HashMap {
    if capacity < 8 {
        capacity = 8;
    }
    var map: ^HashMap = cast(^HashMap) alloc(24);
    map.capacity = capacity;
    map.count = 0;
    map.buckets = vec_ptr_new(capacity);

    var i: i64 = 0;
    while (i < capacity) {
        vec_ptr_push(map.buckets, 0);
        i = i + 1;
    }

    ret map;
}

// Doubles the number of buckets and relinks every node.
@trusted fn hash_map_grow(map: *HashMap) {
    var old: *VecPtr = cast(*VecPtr) map.buckets;
    var old_cap: i64 = map.capacity;
    var new_cap: i64 = old_cap * 2;
    var fresh: ^VecPtr = vec_ptr_new(new_cap);
    var i: i64 = 0;
    while (i < new_cap) {
        vec_ptr_push(fresh, 0);
        i = i + 1;
    }
    i = 0;
    while (i < old_cap) {
        var node: *HashNode = cast(*HashNode) vec_ptr_get(old, i);
        while (node != 0) {
            var next: *HashNode = node.next;
            var index: i64 = node.hash % new_cap;
            node.next = cast(*HashNode) vec_ptr_get(fresh, index);
            vec_ptr_set(fresh, index, node);
            node = next;
        }
        i = i + 1;
    }
    vec_ptr_destroy(old);
    map.buckets = fresh;
    map.capacity = new_cap;
}

@trusted fn hash_map_put(map: *HashMap, key: *String, value: rawptr) {
    if (map == 0 || key == 0) { ret; }

    var h: i64 = hash_djb2(key);
    var index: i64 = h % map.capacity;

    var head: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, index);
    var curr: *HashNode = head;

    while (curr != 0) {
        if (string_eq(curr.key, key) == 1) {
            curr.value = value;
            ret;
        }
        curr = curr.next;
    }

    var node: *HashNode = alloc(32);
    node.key = key;
    node.value = value;
    node.hash = h;
    node.next = head;

    vec_ptr_set(map.buckets, index, node);
    map.count = map.count + 1;

    if (map.count * 4 > map.capacity * 3) {
        hash_map_grow(map);
    }
}

@trusted fn hash_map_get(map: *HashMap, key: *String) -> rawptr {
    if (map == 0 || key == 0) { ret 0; }

    var h: i64 = hash_djb2(key);
    var index: i64 = h % map.capacity;

    var curr: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, index);

    while (curr != 0) {
        if (string_eq(curr.key, key) == 1) {
            ret curr.value;
        }
        curr = curr.next;
    }

    ret 0;
}

@trusted fn hash_map_contains(map: *HashMap, key: *String) -> bool {
    if (map == 0 || key == 0) { ret false; }
    var index: i64 = hash_djb2(key) % map.capacity;
    var curr: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, index);
    while (curr != 0) {
        if (string_eq(curr.key, key) == 1) {
            ret true;
        }
        curr = curr.next;
    }
    ret false;
}

fn hash_map_len(map: *HashMap) -> i64 {
    ret map.count;
}

// Removes `key` and returns its value (0 when absent). The key string itself
// is not freed.
@trusted fn hash_map_remove(map: *HashMap, key: *String) -> rawptr {
    if (map == 0 || key == 0) { ret 0; }
    var index: i64 = hash_djb2(key) % map.capacity;
    var prev: *HashNode = 0;
    var curr: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, index);
    while (curr != 0) {
        if (string_eq(curr.key, key) == 1) {
            if (prev == 0) {
                vec_ptr_set(map.buckets, index, curr.next);
            } else {
                prev.next = curr.next;
            }
            var value: rawptr = curr.value;
            dealloc(curr);
            map.count = map.count - 1;
            ret value;
        }
        prev = curr;
        curr = curr.next;
    }
    ret 0;
}

// Keys as a vector of `*String` (the keys are shared, not copied).
@trusted fn hash_map_keys(map: *HashMap) -> ^VecPtr {
    var out: ^VecPtr = vec_ptr_new(map.count + 1);
    var i: i64 = 0;
    while (i < map.capacity) {
        var node: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, i);
        while (node != 0) {
            vec_ptr_push(out, node.key);
            node = node.next;
        }
        i = i + 1;
    }
    ret out;
}

// Frees the map and its nodes; keys and values are left to the caller.
@trusted fn hash_map_release(map: &mut HashMap) {
    var i: i64 = 0;
    while (i < map.capacity) {
        var node: *HashNode = cast(*HashNode) vec_ptr_get(map.buckets, i);
        while (node != 0) {
            var next: *HashNode = node.next;
            dealloc(node);
            node = next;
        }
        i = i + 1;
    }
}

// Frees a map and its nodes (not the keys and values): it takes the owner, which is dropped here.
fn hash_map_free(map: ^HashMap) { }

@unsafe fn hash_map_destroy(map: *HashMap) { hash_map_free(cast(^HashMap) map); }

std/math.mw:
@no_main

// Math library in plain Marrow (no libm). Results are accurate to a few ulps
// for ordinary arguments. Trigonometric functions reduce their argument with
// a three-part constant (Cody-Waite), which is accurate for |x| below about 1e6;
// larger arguments still give a result, with fewer correct digits.

var PI: f64 = 3.141592653589793;
var TAU: f64 = 6.283185307179586;
var HALF_PI: f64 = 1.5707963267948966;
var E: f64 = 2.718281828459045;
var LN2: f64 = 0.6931471805599453;
var LN10: f64 = 2.302585092994046;
var SQRT2: f64 = 1.4142135623730951;

// ---- bit-level access -------------------------------------------------

@trusted fn f64_to_bits(x: f64) -> u64 {
    var b: u64 = 0;
    var p: *f64 = cast(*f64) raw b;
    *p = x;
    ret b;
}

@trusted fn f64_from_bits(b: u64) -> f64 {
    var x: f64 = 0.0;
    var p: *u64 = cast(*u64) raw x;
    *p = b;
    ret x;
}

fn math_nan() -> f64 {
    ret f64_from_bits(0x7ff8000000000000);
}

fn math_inf() -> f64 {
    ret f64_from_bits(0x7ff0000000000000);
}

fn is_nan(x: f64) -> bool {
    ret x != x;
}

fn is_inf(x: f64) -> bool {
    ret x * 0.5 == x && x != 0.0;
}

fn is_finite(x: f64) -> bool {
    ret !is_nan(x) && !is_inf(x);
}

fn signbit(x: f64) -> bool {
    ret (f64_to_bits(x) >> 63) == 1;
}

// ---- integers -----------------------------------------------------------

fn abs_i64(x: i64) -> i64 {
    if x < 0 {
        ret 0 - x;
    }
    ret x;
}

fn min_i64(a: i64, b: i64) -> i64 {
    if a < b {
        ret a;
    }
    ret b;
}

fn max_i64(a: i64, b: i64) -> i64 {
    if a > b {
        ret a;
    }
    ret b;
}

fn clamp_i64(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        ret lo;
    }
    if x > hi {
        ret hi;
    }
    ret x;
}

fn gcd_i64(a: i64, b: i64) -> i64 {
    a = abs_i64(a);
    b = abs_i64(b);
    while b != 0 {
        var t: i64 = a % b;
        a = b;
        b = t;
    }
    ret a;
}

// Integer power by repeated squaring (wraps on overflow).
fn pow_i64(base: i64, exp: i64) -> i64 {
    var result: i64 = 1;
    var b: i64 = base;
    var e: i64 = exp;
    while e > 0 {
        if (e & 1) == 1 {
            result = result * b;
        }
        b = b * b;
        e = e >> 1;
    }
    ret result;
}

// Largest r with r * r <= n (0 for negative n).
fn isqrt_u64(n: u64) -> u64 {
    if n < 2 {
        ret n;
    }
    var x: u64 = n;
    var y: u64 = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    ret x;
}

// ---- floats: basics -------------------------------------------------------

fn abs(x: f64) -> f64 {
    ret f64_from_bits(f64_to_bits(x) & 0x7fffffffffffffff);
}

fn copysign(x: f64, sign: f64) -> f64 {
    var m: u64 = f64_to_bits(x) & 0x7fffffffffffffff;
    var s: u64 = f64_to_bits(sign) & 0x8000000000000000;
    ret f64_from_bits(m | s);
}

fn min(a: f64, b: f64) -> f64 {
    if is_nan(a) {
        ret b;
    }
    if a < b {
        ret a;
    }
    ret b;
}

fn max(a: f64, b: f64) -> f64 {
    if is_nan(a) {
        ret b;
    }
    if a > b {
        ret a;
    }
    ret b;
}

fn clamp(x: f64, lo: f64, hi: f64) -> f64 {
    ret min(max(x, lo), hi);
}

fn trunc(x: f64) -> f64 {
    if !(abs(x) < 4503599627370496.0) {
        ret x;
    }
    var r: f64 = cast(f64) cast(i64) x;
    ret copysign(r, x);
}

fn floor(x: f64) -> f64 {
    var t: f64 = trunc(x);
    if t > x {
        ret t - 1.0;
    }
    ret t;
}

fn ceil(x: f64) -> f64 {
    var t: f64 = trunc(x);
    if t < x {
        ret t + 1.0;
    }
    ret t;
}

// Rounds half away from zero.
fn round(x: f64) -> f64 {
    if !(abs(x) < 4503599627370496.0) {
        ret x;
    }
    if x < 0.0 {
        ret 0.0 - floor(0.5 - x);
    }
    ret floor(x + 0.5);
}

fn fract(x: f64) -> f64 {
    ret x - trunc(x);
}

// Remainder with the sign of `x` (like C's fmod).
fn fmod(x: f64, y: f64) -> f64 {
    if y == 0.0 || !is_finite(x) || is_nan(y) {
        ret math_nan();
    }
    if is_inf(y) {
        ret x;
    }
    var r: f64 = x - y * trunc(x / y);
    ret r;
}

// ---- sqrt / cbrt / hypot ----------------------------------------------------

fn sqrt(x: f64) -> f64 {
    if x < 0.0 || is_nan(x) {
        ret math_nan();
    }
    if x == 0.0 || is_inf(x) {
        ret x;
    }
    // Initial guess: halve the exponent.
    var g: f64 = f64_from_bits((f64_to_bits(x) >> 1) + 0x1ff8000000000000);
    var i: i64 = 0;
    while i < 6 {
        g = 0.5 * (g + x / g);
        i = i + 1;
    }
    // One last Newton step recovers the final bits.
    ret g + (x - g * g) / (2.0 * g);
}

fn cbrt(x: f64) -> f64 {
    if x == 0.0 || !is_finite(x) {
        ret x;
    }
    var a: f64 = abs(x);
    var g: f64 = exp(ln(a) / 3.0);
    var i: i64 = 0;
    while i < 3 {
        g = g - (g * g * g - a) / (3.0 * g * g);
        i = i + 1;
    }
    ret copysign(g, x);
}

fn hypot(x: f64, y: f64) -> f64 {
    var a: f64 = abs(x);
    var b: f64 = abs(y);
    if is_inf(a) || is_inf(b) {
        ret math_inf();
    }
    if a < b {
        var t: f64 = a;
        a = b;
        b = t;
    }
    if a == 0.0 {
        ret 0.0;
    }
    var r: f64 = b / a;
    ret a * sqrt(1.0 + r * r);
}

// ---- exp / ln / pow ------------------------------------------------------------

// 2^k for -1022 <= k <= 1023.
fn pow2_int(k: i64) -> f64 {
    ret f64_from_bits(cast(u64) (k + 1023) << 52);
}

fn exp(x: f64) -> f64 {
    if is_nan(x) {
        ret x;
    }
    if x > 709.782712893384 {
        ret math_inf();
    }
    if x < -745.1332191019411 {
        ret 0.0;
    }
    var k: f64 = round(x / LN2);
    var r: f64 = x - k * 0.6931471803691238 - k * 1.9082149292705877e-10;
    // Taylor series of e^r for |r| <= ln(2) / 2, evaluated with Horner's rule.
    var p: f64 = 1.0;
    var n: i64 = 17;
    while n >= 1 {
        p = 1.0 + r * p / (cast(f64) n);
        n = n - 1;
    }
    var ki: i64 = cast(i64) k;
    var h: i64 = ki / 2;
    ret p * pow2_int(h) * pow2_int(ki - h);
}

fn ln(x: f64) -> f64 {
    if is_nan(x) || x < 0.0 {
        ret math_nan();
    }
    if x == 0.0 {
        ret 0.0 - math_inf();
    }
    if is_inf(x) {
        ret x;
    }
    var bits: u64 = f64_to_bits(x);
    var e: i64 = cast(i64) ((bits >> 52) & 2047);
    if e == 0 {
        // Subnormal: scale up by 2^54 first.
        ret ln(x * 18014398509481984.0) - 54.0 * LN2;
    }
    e = e - 1023;
    var m: f64 = f64_from_bits((bits & 0x000fffffffffffff) | 0x3ff0000000000000);
    if m > SQRT2 {
        m = m * 0.5;
        e = e + 1;
    }
    var s: f64 = (m - 1.0) / (m + 1.0);
    var s2: f64 = s * s;
    // ln(m) = 2 * (s + s^3/3 + s^5/5 + ...)
    var sum: f64 = 0.0;
    var n: i64 = 31;
    while n >= 1 {
        sum = 1.0 / (cast(f64) n) + s2 * sum;
        n = n - 2;
    }
    ret (cast(f64) e) * LN2 + 2.0 * s * sum;
}

fn log2(x: f64) -> f64 {
    ret ln(x) / LN2;
}

fn log10(x: f64) -> f64 {
    ret ln(x) / LN10;
}

fn is_integer_valued(y: f64) -> bool {
    ret is_finite(y) && trunc(y) == y;
}

fn pow(x: f64, y: f64) -> f64 {
    if y == 0.0 {
        ret 1.0;
    }
    if is_nan(x) || is_nan(y) {
        ret math_nan();
    }
    if x == 0.0 {
        if y < 0.0 {
            ret math_inf();
        }
        ret 0.0;
    }
    if is_integer_valued(y) && abs(y) < 1073741824.0 {
        var n: i64 = cast(i64) abs(y);
        var result: f64 = 1.0;
        var b: f64 = x;
        while n > 0 {
            if (n & 1) == 1 {
                result = result * b;
            }
            b = b * b;
            n = n >> 1;
        }
        if y < 0.0 {
            ret 1.0 / result;
        }
        ret result;
    }
    if x < 0.0 {
        ret math_nan();
    }
    ret exp(y * ln(x));
}

fn sinh(x: f64) -> f64 {
    if abs(x) < 0.0001 {
        ret x;
    }
    ret (exp(x) - exp(0.0 - x)) * 0.5;
}

fn cosh(x: f64) -> f64 {
    ret (exp(x) + exp(0.0 - x)) * 0.5;
}

fn tanh(x: f64) -> f64 {
    if x > 20.0 {
        ret 1.0;
    }
    if x < -20.0 {
        ret -1.0;
    }
    if abs(x) < 0.0001 {
        ret x;
    }
    var a: f64 = exp(x);
    var b: f64 = exp(0.0 - x);
    ret (a - b) / (a + b);
}

// ---- trigonometry ----------------------------------------------------------------

// Taylor series of sin on |r| <= pi/4.
fn sin_kernel(r: f64) -> f64 {
    var r2: f64 = r * r;
    var p: f64 = 1.0;
    var n: i64 = 19;
    while n >= 3 {
        p = 1.0 - r2 * p / (cast(f64) (n * (n - 1)));
        n = n - 2;
    }
    ret r * p;
}

// Taylor series of cos on |r| <= pi/4.
fn cos_kernel(r: f64) -> f64 {
    var r2: f64 = r * r;
    var p: f64 = 1.0;
    var n: i64 = 20;
    while n >= 2 {
        p = 1.0 - r2 * p / (cast(f64) (n * (n - 1)));
        n = n - 2;
    }
    ret p;
}

// Returns the quadrant (0..3) of x and stores the reduced angle in `*r`.
@trusted fn trig_reduce(x: f64, r: *f64) -> i64 {
    var k: f64 = round(x / HALF_PI);
    *r = ((x - k * 1.5707963267341256) - k * 6.077100506303966e-11) - k * 2.0222662487111665e-21;
    var q: i64 = cast(i64) fmod(k, 4.0);
    if q < 0 {
        q = q + 4;
    }
    ret q;
}

@trusted fn sin(x: f64) -> f64 {
    if !is_finite(x) {
        ret math_nan();
    }
    var r: f64 = 0.0;
    var q: i64 = trig_reduce(x, raw r);
    if q == 0 {
        ret sin_kernel(r);
    }
    if q == 1 {
        ret cos_kernel(r);
    }
    if q == 2 {
        ret 0.0 - sin_kernel(r);
    }
    ret 0.0 - cos_kernel(r);
}

@trusted fn cos(x: f64) -> f64 {
    if !is_finite(x) {
        ret math_nan();
    }
    var r: f64 = 0.0;
    var q: i64 = trig_reduce(x, raw r);
    if q == 0 {
        ret cos_kernel(r);
    }
    if q == 1 {
        ret 0.0 - sin_kernel(r);
    }
    if q == 2 {
        ret 0.0 - cos_kernel(r);
    }
    ret sin_kernel(r);
}

fn tan(x: f64) -> f64 {
    ret sin(x) / cos(x);
}

// Taylor series of atan on |x| <= tan(pi/12).
fn atan_kernel(x: f64) -> f64 {
    var x2: f64 = x * x;
    var sum: f64 = 0.0;
    var n: i64 = 41;
    while n >= 1 {
        sum = 1.0 / (cast(f64) n) - x2 * sum;
        n = n - 2;
    }
    ret x * sum;
}

fn atan(x: f64) -> f64 {
    if is_nan(x) {
        ret x;
    }
    var a: f64 = abs(x);
    var r: f64 = 0.0;
    if a > 1.0 {
        r = HALF_PI - atan_pos(1.0 / a);
    } else {
        r = atan_pos(a);
    }
    ret copysign(r, x);
}

// atan for 0 <= x <= 1.
fn atan_pos(x: f64) -> f64 {
    if x > 0.2679491924311227 {
        var s3: f64 = 1.7320508075688772;
        ret 0.5235987755982988 + atan_kernel((x * s3 - 1.0) / (s3 + x));
    }
    ret atan_kernel(x);
}

fn atan2(y: f64, x: f64) -> f64 {
    if is_nan(x) || is_nan(y) {
        ret math_nan();
    }
    if x == 0.0 {
        if y > 0.0 {
            ret HALF_PI;
        }
        if y < 0.0 {
            ret 0.0 - HALF_PI;
        }
        ret 0.0;
    }
    var a: f64 = atan(y / x);
    if x > 0.0 {
        ret a;
    }
    if y >= 0.0 {
        ret a + PI;
    }
    ret a - PI;
}

fn asin(x: f64) -> f64 {
    if x > 1.0 || x < -1.0 {
        ret math_nan();
    }
    ret atan2(x, sqrt(1.0 - x * x));
}

fn acos(x: f64) -> f64 {
    if x > 1.0 || x < -1.0 {
        ret math_nan();
    }
    ret atan2(sqrt(1.0 - x * x), x);
}

fn to_radians(deg: f64) -> f64 {
    ret deg * (PI / 180.0);
}

fn to_degrees(rad: f64) -> f64 {
    ret rad * (180.0 / PI);
}

std/mem.mw:
@no_main

@import("heap.mw")

// Thin, stable names over the libc-free allocator (std/heap.mw) and the
// memory primitives (std/raw.mw).

fn alloc(size: i64) -> *u8 {
    ret heap_alloc(size);
}

@unsafe fn realloc(ptr: *u8, new_size: i64) -> *u8 {
    ret heap_realloc(ptr, new_size);
}

@unsafe fn dealloc(ptr: *u8) {
    heap_free(ptr);
}

@unsafe fn mem_copy(dest: *u8, src: *u8, count: i64) {
    raw_copy(dest, src, count);
}

@unsafe fn mem_zero(dest: *u8, count: i64) {
    raw_zero(dest, count);
}

@drop(arena_release)
struct Arena {
    buffer: *u8;
    capacity: i64;
    offset: i64;
}

@trusted fn arena_new(capacity: i64) -> ^Arena {
    var a: ^Arena = cast(^Arena) alloc(24);
    a.buffer = alloc(capacity);
    a.capacity = capacity;
    a.offset = 0;
    ret a;
}

@trusted fn arena_alloc(a: *Arena, size: i64) -> *u8 {
    if (a.offset + size > a.capacity) {
        ret 0;
    }

    var ptr: *u8 = a.buffer + a.offset;
    a.offset = a.offset + size;
    ret ptr;
}

fn arena_reset(a: *Arena) {
    a.offset = 0;
}

// Run by the drop: frees the buffer, then the struct is freed.
@trusted fn arena_release(a: &mut Arena) {
    dealloc(a.buffer);
}

// Frees an arena: it takes the owner, which is dropped here.
fn arena_free(a: ^Arena) { }

// Frees an arena that is only known by a plain pointer: the caller was its owner.
@unsafe fn arena_destroy(a: *Arena) { arena_free(cast(^Arena) a); }

std/net.mw:
@no_main

@import("heap.mw")
@import("text.mw")
@import("fs.mw")
@import("rand.mw")

// TCP and UDP over IPv4, plus a small DNS resolver. No libc: every function
// is built on the socket calls of the platform layer.
//
// Addresses are `u32` values in host order (a.b.c.d -> a<<24 | b<<16 | c<<8 | d).
// Functions returning `i64` give a file descriptor or a negative errno.

struct Timeval {
    sec: i64;
    usec: i64;
}

fn ip4(a: i64, b: i64, c: i64, d: i64) -> u32 {
    ret cast(u32) ((a << 24) | (b << 16) | (c << 8) | d);
}

fn ip4_octet(ip: u32, index: i64) -> i64 {
    ret cast(i64) ((ip >> cast(i64) (24 - index * 8)) & 255);
}

// Parses "a.b.c.d" (exactly four decimal parts, each 0..255).
@trusted fn ip4_parse(s: *u8, out: *u32) -> bool {
    var value: i64 = 0;
    var part: i64 = 0;
    var digits: i64 = 0;
    var parts: i64 = 0;
    var i: i64 = 0;
    while 1 == 1 {
        var c: u8 = s[i];
        if c >= 48 && c <= 57 {
            part = part * 10 + cast(i64) (c - 48);
            digits = digits + 1;
            if part > 255 || digits > 3 {
                ret false;
            }
        } else {
            if (c == 46 || c == 0) && digits > 0 {
                value = (value << 8) | part;
                parts = parts + 1;
                part = 0;
                digits = 0;
                if c == 0 {
                    if parts != 4 {
                        ret false;
                    }
                    *out = cast(u32) value;
                    ret true;
                }
                if parts == 4 {
                    ret false;
                }
            } else {
                ret false;
            }
        }
        i = i + 1;
    }
    ret false;
}

// "a.b.c.d" into `buf` (at most 15 bytes); returns the length.
@trusted fn ip4_format(buf: *u8, ip: u32) -> i64 {
    var len: i64 = 0;
    var i: i64 = 0;
    while i < 4 {
        len = len + fmt_u64(buf + len, cast(u64) ip4_octet(ip, i), 10);
        if i < 3 {
            buf[len] = 46;
            len = len + 1;
        }
        i = i + 1;
    }
    ret len;
}

// ---- sockets ------------------------------------------------------------------

@trusted fn net_close(fd: i64) {
    if fd >= 0 {
        sys_close(cast(i32) fd);
    }
}

@trusted fn net_set_timeout_ms(fd: i64, ms: i64) -> i64 {
    var tv: Timeval = Timeval { sec: ms / 1000, usec: (ms % 1000) * 1000 };
    var a: i64 = sys_setsockopt(cast(i32) fd, SOL_SOCKET, SO_RCVTIMEO, cast(*u8) raw tv, 16);
    var b: i64 = sys_setsockopt(cast(i32) fd, SOL_SOCKET, SO_SNDTIMEO, cast(*u8) raw tv, 16);
    if a < 0 {
        ret a;
    }
    ret b;
}

@trusted fn net_set_nodelay(fd: i64) -> i64 {
    var one: i32 = 1;
    ret sys_setsockopt(cast(i32) fd, IPPROTO_TCP, TCP_NODELAY, cast(*u8) raw one, 4);
}

@trusted fn net_sockaddr(buf: *u8, ip: u32, port: i64) {
    sys_sockaddr_in(buf, ip4_octet(ip, 0), ip4_octet(ip, 1), ip4_octet(ip, 2), ip4_octet(ip, 3), port);
}

@trusted fn tcp_connect_ip(ip: u32, port: i64) -> i64 {
    var fd: i64 = sys_socket(AF_INET, SOCK_STREAM, 0);
    if fd < 0 {
        ret fd;
    }
    var addr: *u8 = heap_alloc(16);
    net_sockaddr(addr, ip, port);
    var r: i64 = sys_connect(cast(i32) fd, addr, 16);
    heap_free(addr);
    if r < 0 {
        sys_close(cast(i32) fd);
        ret r;
    }
    net_set_nodelay(fd);
    ret fd;
}

// Listens on `ip:port` (port 0 picks a free one; see `net_local_port`).
@trusted fn tcp_listen_on(ip: u32, port: i64, backlog: i64) -> i64 {
    var fd: i64 = sys_socket(AF_INET, SOCK_STREAM, 0);
    if fd < 0 {
        ret fd;
    }
    var one: i32 = 1;
    sys_setsockopt(cast(i32) fd, SOL_SOCKET, SO_REUSEADDR, cast(*u8) raw one, 4);
    var addr: *u8 = heap_alloc(16);
    net_sockaddr(addr, ip, port);
    var r: i64 = sys_bind(cast(i32) fd, addr, 16);
    heap_free(addr);
    if r < 0 {
        sys_close(cast(i32) fd);
        ret r;
    }
    r = sys_listen(cast(i32) fd, cast(i32) backlog);
    if r < 0 {
        sys_close(cast(i32) fd);
        ret r;
    }
    ret fd;
}

// All interfaces.
fn tcp_listen(port: i64, backlog: i64) -> i64 {
    ret tcp_listen_on(0, port, backlog);
}

// Accepts one connection. `peer` (may be null) receives the client address.
@trusted fn tcp_accept(fd: i64, peer: *u32) -> i64 {
    var addr: *u8 = heap_alloc(32);
    var len: i32 = 32;
    var c: i64 = sys_accept(cast(i32) fd, addr, raw len);
    while c == -4 {
        len = 32;
        c = sys_accept(cast(i32) fd, addr, raw len);
    }
    if c >= 0 && peer != null {
        var off: i64 = 4;
        *peer = ip4(cast(i64) addr[off], cast(i64) addr[off + 1], cast(i64) addr[off + 2], cast(i64) addr[off + 3]);
    }
    heap_free(addr);
    if c >= 0 {
        net_set_nodelay(c);
    }
    ret c;
}

// Port a socket is bound to (host order), or a negative errno.
@trusted fn net_local_port(fd: i64) -> i64 {
    var addr: *u8 = heap_alloc(32);
    var len: i32 = 32;
    var r: i64 = sys_getsockname(cast(i32) fd, addr, raw len);
    if r < 0 {
        heap_free(addr);
        ret r;
    }
    var port: i64 = ((cast(i64) addr[2]) << 8) | (cast(i64) addr[3]);
    heap_free(addr);
    ret port;
}

// Reads up to `n` bytes (0 means the peer closed the connection).
@trusted fn net_read(fd: i64, buf: *u8, n: i64) -> i64 {
    var r: i64 = sys_recv(cast(i32) fd, buf, cast(u64) n);
    while r == -4 {
        r = sys_recv(cast(i32) fd, buf, cast(u64) n);
    }
    ret r;
}

// Sends every byte. Returns 0 on success or a negative errno.
@trusted fn net_write_all(fd: i64, buf: *u8, n: i64) -> i64 {
    var done: i64 = 0;
    while done < n {
        var r: i64 = sys_send(cast(i32) fd, buf + done, cast(u64) (n - done));
        if r == -4 {
            r = 0;
        } else {
            if r < 0 {
                ret r;
            }
        }
        done = done + r;
    }
    ret 0;
}

fn net_write_str(fd: i64, s: *u8) -> i64 {
    ret net_write_all(fd, s, str_len(s));
}

// Stops sending (the peer then reads end-of-file) but keeps reading open.
@trusted fn net_shutdown_write(fd: i64) {
    sys_shutdown(cast(i32) fd, 1);
}

// ---- UDP ------------------------------------------------------------------------

@trusted fn udp_socket() -> i64 {
    ret sys_socket(AF_INET, SOCK_DGRAM, 0);
}

@trusted fn udp_send_to(fd: i64, ip: u32, port: i64, buf: *u8, n: i64) -> i64 {
    var addr: *u8 = heap_alloc(16);
    net_sockaddr(addr, ip, port);
    var r: i64 = sys_sendto(cast(i32) fd, buf, cast(u64) n, addr, 16);
    heap_free(addr);
    ret r;
}

@trusted fn udp_recv(fd: i64, buf: *u8, n: i64) -> i64 {
    ret sys_recvfrom(cast(i32) fd, buf, cast(u64) n);
}

// ---- DNS ------------------------------------------------------------------------

@trusted fn be16_at(buf: *u8, i: i64) -> i64 {
    ret ((cast(i64) buf[i]) << 8) | (cast(i64) buf[i + 1]);
}

// Skips a (possibly compressed) domain name; returns the index after it.
@trusted fn dns_skip_name(buf: *u8, len: i64, i: i64) -> i64 {
    while i < len {
        var c: i64 = cast(i64) buf[i];
        if c == 0 {
            ret i + 1;
        }
        if (c & 192) == 192 {
            ret i + 2;
        }
        i = i + 1 + c;
    }
    ret -1;
}

// Builds an A query for `name` into `buf`; returns its length or -1.
@trusted fn dns_build_query(buf: *u8, name: *u8, id: i64) -> i64 {
    buf[0] = cast(u8) (id >> 8);
    buf[1] = cast(u8) (id & 255);
    buf[2] = 1;
    buf[3] = 0;
    buf[4] = 0;
    buf[5] = 1;
    buf[6] = 0;
    buf[7] = 0;
    buf[8] = 0;
    buf[9] = 0;
    buf[10] = 0;
    buf[11] = 0;
    var pos: i64 = 12;
    var i: i64 = 0;
    while 1 == 1 {
        var start: i64 = i;
        while name[i] != 46 && name[i] != 0 {
            i = i + 1;
        }
        var n: i64 = i - start;
        if n == 0 || n > 63 {
            ret -1;
        }
        buf[pos] = cast(u8) n;
        mem_copy(buf + pos + 1, name + start, n);
        pos = pos + 1 + n;
        if name[i] == 0 {
            buf[pos] = 0;
            buf[pos + 1] = 0;
            buf[pos + 2] = 1;
            buf[pos + 3] = 0;
            buf[pos + 4] = 1;
            ret pos + 5;
        }
        i = i + 1;
    }
    ret -1;
}

// Extracts the first IPv4 address of a response to our query.
@trusted fn dns_parse_response(buf: *u8, len: i64, id: i64, out: *u32) -> bool {
    if len < 12 || be16_at(buf, 0) != id {
        ret false;
    }
    if (cast(i64) buf[3]) & 15 != 0 {
        ret false;
    }
    var qd: i64 = be16_at(buf, 4);
    var an: i64 = be16_at(buf, 6);
    var i: i64 = 12;
    var q: i64 = 0;
    while q < qd {
        i = dns_skip_name(buf, len, i);
        if i < 0 {
            ret false;
        }
        i = i + 4;
        q = q + 1;
    }
    var a: i64 = 0;
    while a < an {
        i = dns_skip_name(buf, len, i);
        if i < 0 || i + 10 > len {
            ret false;
        }
        var kind: i64 = be16_at(buf, i);
        var rdlen: i64 = be16_at(buf, i + 8);
        i = i + 10;
        if i + rdlen > len {
            ret false;
        }
        if kind == 1 && rdlen == 4 {
            *out = ip4(cast(i64) buf[i], cast(i64) buf[i + 1], cast(i64) buf[i + 2], cast(i64) buf[i + 3]);
            ret true;
        }
        i = i + rdlen;
        a = a + 1;
    }
    ret false;
}

// First `nameserver` line of /etc/resolv.conf that is an IPv4 address.
@trusted fn dns_nameserver(out: *u32) -> bool {
    var conf: ^String = read_to_string("/etc/resolv.conf");
    if conf == 0 {
        ret false;
    }
    var lines: ^VecPtr = str_split(conf.data, 10);
    var i: i64 = 0;
    var found: bool = false;
    while i < lines.len && !found {
        var line: *u8 = cast(*u8) vec_ptr_get(lines, i);
        if str_starts_with(line, "nameserver") {
            var rest: *u8 = str_trim(line + 10);
            found = ip4_parse(rest, out);
            dealloc(rest);
        }
        i = i + 1;
    }
    string_free(conf);
    ret found;
}

// Looks `name` up in /etc/hosts (IPv4 entries only).
@trusted fn dns_from_hosts(name: *u8, out: *u32) -> bool {
    var hosts: ^String = read_to_string("/etc/hosts");
    if hosts == 0 {
        ret false;
    }
    var lines: ^VecPtr = str_split(hosts.data, 10);
    var i: i64 = 0;
    var found: bool = false;
    while i < lines.len && !found {
        var line: *u8 = cast(*u8) vec_ptr_get(lines, i);
        var hash: i64 = str_find_char(line, 35);
        var clean: *u8 = line;
        if hash >= 0 {
            clean = str_dup_n(line, hash);
        }
        var fields: ^VecPtr = str_split(clean, 32);
        var ip: u32 = 0;
        var j: i64 = 0;
        var have_ip: bool = false;
        while j < fields.len && !found {
            var f: *u8 = cast(*u8) vec_ptr_get(fields, j);
            var t: *u8 = str_trim(f);
            if t[0] != 0 {
                if !have_ip {
                    have_ip = ip4_parse(t, raw ip);
                    if !have_ip {
                        j = fields.len;
                    }
                } else {
                    if str_eq_nocase(t, name) {
                        *out = ip;
                        found = true;
                    }
                }
            }
            dealloc(t);
            j = j + 1;
        }
        i = i + 1;
    }
    string_free(hosts);
    ret found;
}

// Resolves a host name or dotted address to IPv4. Tries, in order: literal
// address, "localhost", /etc/hosts, then a UDP query to the first IPv4
// nameserver of /etc/resolv.conf.
@trusted fn dns_resolve(name: *u8, out: *u32) -> bool {
    if ip4_parse(name, out) {
        ret true;
    }
    if str_eq_nocase(name, "localhost") {
        *out = ip4(127, 0, 0, 1);
        ret true;
    }
    if dns_from_hosts(name, out) {
        ret true;
    }
    var server: u32 = 0;
    if !dns_nameserver(raw server) {
        ret false;
    }
    var fd: i64 = udp_socket();
    if fd < 0 {
        ret false;
    }
    net_set_timeout_ms(fd, 2000);
    var query: *u8 = heap_alloc(512);
    var reply: *u8 = heap_alloc(1500);
    var id: i64 = cast(i64) (random_u64() & 65535);
    var qlen: i64 = dns_build_query(query, name, id);
    var ok: bool = false;
    var attempt: i64 = 0;
    while qlen > 0 && attempt < 3 && !ok {
        if udp_send_to(fd, server, 53, query, qlen) >= 0 {
            var n: i64 = udp_recv(fd, reply, 1500);
            if n > 0 {
                ok = dns_parse_response(reply, n, id, out);
                if !ok {
                    attempt = 3;
                }
            }
        }
        attempt = attempt + 1;
    }
    heap_free(query);
    heap_free(reply);
    sys_close(cast(i32) fd);
    ret ok;
}

// Resolves `host` and connects.
@trusted fn tcp_connect(host: *u8, port: i64) -> i64 {
    var ip: u32 = 0;
    if !dns_resolve(host, raw ip) {
        ret -2;
    }
    ret tcp_connect_ip(ip, port);
}

std/option.mw:
// `Option<T>` and `Result<T, E>`: a value that may be missing, and a value or an error.
//
// This module is not part of `std/std.mw`: names are shared by the whole program, so a program
// that defines its own `Option` or `Result` keeps working. Import it where you need it:
//     @import("std/option.mw")
// Generic functions take their types explicitly: `option_unwrap_or::<i64>(o, 0)`.

enum Option<T> { Some(T); None; }

enum Result<T, E> { Ok(T); Err(E); }

@trusted fn option_is_some<T>(o: Option<T>) -> bool {
    match o {
        Option::<T>::Some(v) => { ret true; }
        else => { ret false; }
    }
}

@trusted fn option_is_none<T>(o: Option<T>) -> bool {
    match o {
        Option::<T>::Some(v) => { ret false; }
        else => { ret true; }
    }
}

// The value, or `fallback` when there is none.
@trusted fn option_unwrap_or<T>(o: Option<T>, fallback: T) -> T {
    match o {
        Option::<T>::Some(v) => { ret v; }
        else => { ret fallback; }
    }
}

@trusted fn result_is_ok<T, E>(r: Result<T, E>) -> bool {
    match r {
        Result::<T, E>::Ok(v) => { ret true; }
        else => { ret false; }
    }
}

@trusted fn result_is_err<T, E>(r: Result<T, E>) -> bool {
    match r {
        Result::<T, E>::Ok(v) => { ret false; }
        else => { ret true; }
    }
}

// The value, or `fallback` when it is an error.
@trusted fn result_unwrap_or<T, E>(r: Result<T, E>, fallback: T) -> T {
    match r {
        Result::<T, E>::Ok(v) => { ret v; }
        else => { ret fallback; }
    }
}

// The error, or `fallback` when it is a value.
@trusted fn result_err_or<T, E>(r: Result<T, E>, fallback: E) -> E {
    match r {
        Result::<T, E>::Err(e) => { ret e; }
        else => { ret fallback; }
    }
}

// The value as an `Option`, dropping the error.
@trusted fn result_ok<T, E>(r: Result<T, E>) -> Option<T> {
    match r {
        Result::<T, E>::Ok(v) => { ret Option::<T>::Some(v); }
        else => { ret Option::<T>::None; }
    }
}

