    ret syscall(133, cast(i64) fd, cast(i64) buf, cast(i64) len, 0, 0, 0);
}

@unsafe fn sys_recv(fd: i32, buf: *u8, len: u64) -> i64 {
    ret syscall(29, cast(i64) fd, cast(i64) buf, cast(i64) len, 0, 0, 0);
}

@unsafe fn sys_sendto(fd: i32, buf: *u8, len: u64, addr: *u8, addr_len: i32) -> i64 {
    ret syscall(133, cast(i64) fd, cast(i64) buf, cast(i64) len, 0, cast(i64) addr, cast(i64) addr_len);
}

@unsafe fn sys_recvfrom(fd: i32, buf: *u8, len: u64) -> i64 {
    ret syscall(29, cast(i64) fd, cast(i64) buf, cast(i64) len, 0, 0, 0);
}

@unsafe fn sys_setsockopt(fd: i32, level: i32, name: i32, val: *u8, len: i32) -> i64 {
