    var c: i64 = 0;
    var f: i64 = 0;
    syscall(K32_QPC, cast(i64) raw c, 0, 0, 0, 0, 0);
    syscall(K32_QPF, cast(i64) raw f, 0, 0, 0, 0, 0);
    if f <= 0 {
