// NUL-separated "NAME=value" strings is turned into a pointer array.
@unsafe fn sys_env_block(argc: i64, argv: i64) -> *i64 {
    var env_block: *u8 = cast(*u8) syscall(K32_ENV_STRINGS, 0, 0, 0, 0, 0, 0);
    if env_block == null {
        ret null;
