// The buffer of a string, which now belongs to the caller (free it with `dealloc`); the `String`
// itself is freed. The NUL-terminated text stays valid.
fn string_into_data(s: ^String) -> *u8 {
    var d: *u8 = s.data;
    s.data = null;
