}

// Frees a string: it takes the owner, which is dropped here.
fn string_free(s: ^String) { }

// Frees a string that is only known by a plain pointer: the caller was its owner.
@unsafe fn string_destroy(s: *String) { string_free(cast(^String) s); }

fn string_eq(a: *String, b: *String) -> i32 {
    if (a == 0 || b == 0) { ret 0; }
    if (a == b) { ret 1; } // Même pointeur
    if (a.len != b.len) { ret 0; }

    ret cast(i32) str_eq(a.data, b.data);
