@trusted fn string_cmp(a: *String, b: *String) -> i32 {
    if (a == 0 || b == 0) { ret 0; }
    if (a.data == 0 || b.data == 0) { ret 0; }

    var min_len: i64 = a.len;
    if (b.len < min_len) {
        min_len = b.len;
    }

    var i: i64 = 0;
    while (i < min_len) {
        var ptr_a: *u8 = a.data + i;
        var ptr_b: *u8 = b.data + i;
        var ca: u8 = *ptr_a;
        var cb: u8 = *ptr_b;

        if (ca < cb) { ret -1; }
        if (ca > cb) { ret 1; }

        i = i + 1;
    }

    if (a.len < b.len) { ret -1; }
    if (a.len > b.len) { ret 1; }

    ret 0;
}

