@no_main

@import("os.mw")
@import("fmt.mw")

// Clocks, sleeping and calendar conversion (proleptic Gregorian, UTC).

// Nanoseconds since 1970-01-01 00:00:00 UTC (negative on error).
@trusted fn time_now_ns() -> i64 {
    ret sys_clock_ns(0);
}

// Nanoseconds from an arbitrary starting point; never goes backwards.
@trusted fn time_mono_ns() -> i64 {
    ret sys_clock_ns(1);
}

fn time_unix() -> i64 {
    ret time_now_ns() / 1000000000;
}

@trusted fn sleep_ns(ns: i64) {
    sys_sleep_ns(ns);
}

@trusted fn sleep_ms(ms: i64) {
    sys_sleep_ns(ms * 1000000);
}

struct DateTime {
    year: i64;
    month: i64;   // 1..12
    day: i64;     // 1..31
    hour: i64;
    minute: i64;
    second: i64;
    weekday: i64; // 0 = Sunday
    yday: i64;    // 0-based day of the year
}

fn is_leap_year(y: i64) -> bool {
    if y % 400 == 0 {
        ret true;
    }
    if y % 100 == 0 {
        ret false;
    }
    ret y % 4 == 0;
}

fn days_in_month(y: i64, m: i64) -> i64 {
    if m == 2 {
        if is_leap_year(y) {
            ret 29;
        }
        ret 28;
    }
    if m == 4 || m == 6 || m == 9 || m == 11 {
        ret 30;
    }
    ret 31;
}

// Days since 1970-01-01 for a civil date (Howard Hinnant's algorithm).
fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    if m <= 2 {
        y = y - 1;
    }
    var era: i64 = y / 400;
    if y < 0 {
        era = (y - 399) / 400;
    }
    var yoe: i64 = y - era * 400;
    var mp: i64 = m + 9;
    if m > 2 {
        mp = m - 3;
    }
    var doy: i64 = (153 * mp + 2) / 5 + d - 1;
    var doe: i64 = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    ret era * 146097 + doe - 719468;
}

// Seconds since the epoch -> broken-down UTC time.
fn datetime_from_unix(t: i64) -> DateTime {
    var days: i64 = t / 86400;
    var rem: i64 = t % 86400;
    if rem < 0 {
        rem = rem + 86400;
        days = days - 1;
    }
    var z: i64 = days + 719468;
    var era: i64 = z / 146097;
    if z < 0 {
        era = (z - 146096) / 146097;
    }
    var doe: i64 = z - era * 146097;
    var yoe: i64 = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    var y: i64 = yoe + era * 400;
    var doy: i64 = doe - (365 * yoe + yoe / 4 - yoe / 100);
    var mp: i64 = (5 * doy + 2) / 153;
    var d: i64 = doy - (153 * mp + 2) / 5 + 1;
    var m: i64 = mp + 3;
    if mp >= 10 {
        m = mp - 9;
    }
    if m <= 2 {
        y = y + 1;
    }
    var wd: i64 = (days + 4) % 7;
    if wd < 0 {
        wd = wd + 7;
    }
    var yd: i64 = days - days_from_civil(y, 1, 1);
    ret DateTime { year: y, month: m, day: d, hour: rem / 3600, minute: (rem % 3600) / 60, second: rem % 60, weekday: wd, yday: yd };
}

fn datetime_to_unix(dt: DateTime) -> i64 {
    ret days_from_civil(dt.year, dt.month, dt.day) * 86400 + dt.hour * 3600 + dt.minute * 60 + dt.second;
}

@trusted fn time_pad2(buf: *u8, n: i64) {
    buf[0] = cast(u8) (48 + n / 10);
    buf[1] = cast(u8) (48 + n % 10);
}

// "YYYY-MM-DDTHH:MM:SSZ" (20 bytes, no terminator) -> returns 20.
@trusted fn datetime_format_iso(buf: *u8, dt: DateTime) -> i64 {
    var y: i64 = dt.year;
    buf[0] = cast(u8) (48 + (y / 1000) % 10);
    buf[1] = cast(u8) (48 + (y / 100) % 10);
    buf[2] = cast(u8) (48 + (y / 10) % 10);
    buf[3] = cast(u8) (48 + y % 10);
    buf[4] = 45;
    time_pad2(buf + 5, dt.month);
    buf[7] = 45;
    time_pad2(buf + 8, dt.day);
    buf[10] = 84;
    time_pad2(buf + 11, dt.hour);
    buf[13] = 58;
    time_pad2(buf + 14, dt.minute);
    buf[16] = 58;
    time_pad2(buf + 17, dt.second);
    buf[19] = 90;
    ret 20;
}

std/tls.mw:
@no_main

@import("raw.mw")
@import("heap.mw")
@import("vec.mw")
@import("hash.mw")
@import("chacha.mw")
@import("aes.mw")
@import("x25519.mw")
@import("rsa.mw")
@import("ecdsa.mw")
@import("x509.mw")
@import("net.mw")
@import("rand.mw")
@import("time.mw")

// TLS 1.3 client (RFC 8446).
//
//   * cipher suites TLS_CHACHA20_POLY1305_SHA256, TLS_AES_128_GCM_SHA256
//   * key exchange  X25519
//   * server auth   X.509 chain verified against the trust store and the host
//                   name, CertificateVerify with ECDSA (P-256/P-384) or
//                   RSA-PSS, and the Finished MAC.  There is no way to
//                   skip verification.
//
// Usage:
//     var fd: i64 = tcp_connect(host, 443);
//     var roots: *VecPtr = vec_ptr_new(16);  x509_load_system_roots(roots);
//     var t: *Tls = tls_connect(fd, host, roots);   // null on failure
//     tls_write(t, data, n);  tls_read(t, buf, cap);  tls_close(t);

var TLS_ERR: *u8 = "";

fn tls_last_error() -> *u8 { ret TLS_ERR; }

@drop(tls_release)
struct Tls {
    fd: i64;
    c_key: *u8;
    c_iv: *u8;
    c_seq: i64;
    s_key: *u8;
    s_iv: *u8;
    s_seq: i64;
    c_secret: *u8;
    s_secret: *u8;
    encrypted: i64;
    th: *u8;
    thlen: i64;
    thcap: i64;
    hs: *u8;
    hslen: i64;
    hscap: i64;
    rbuf: *u8;
    rpos: i64;
    rlen: i64;
    eof: i64;
    failed: i64;
    suite: i64;
}

fn tls_fail(msg: *u8) -> bool {
    TLS_ERR = msg;
    ret false;
}

// ---------------------------------------------------------------- byte builder

struct Bld {
    p: *u8;
    len: i64;
}

@trusted fn bld_u8(b: *Bld, v: i64) { b.p[b.len] = cast(u8) v; b.len = b.len + 1; }
fn bld_u16(b: *Bld, v: i64) { bld_u8(b, v >> 8); bld_u8(b, v & 255); }
fn bld_u24(b: *Bld, v: i64) { bld_u8(b, v >> 16); bld_u8(b, (v >> 8) & 255); bld_u8(b, v & 255); }
@trusted fn bld_bytes(b: *Bld, src: *u8, n: i64) { raw_copy(b.p + b.len, src, n); b.len = b.len + n; }
@trusted fn bld_put16_at(b: *Bld, at: i64, v: i64) { b.p[at] = cast(u8) (v >> 8); b.p[at + 1] = cast(u8) (v & 255); }

@trusted fn rd16(p: *u8) -> i64 { ret ((cast(i64) p[0]) << 8) | (cast(i64) p[1]); }
@trusted fn rd24(p: *u8) -> i64 { ret ((cast(i64) p[0]) << 16) | ((cast(i64) p[1]) << 8) | (cast(i64) p[2]); }

// ---------------------------------------------------------------- raw I/O

@trusted fn tls_recv_exact(fd: i64, buf: *u8, n: i64) -> bool {
    var done: i64 = 0;
    while done < n {
        var r: i64 = net_read(fd, buf + done, n - done);
        if r <= 0 { ret false; }
        done = done + r;
    }
    ret true;
}

// ---------------------------------------------------------------- key schedule

// HKDF-Expand-Label for SHA-256 (RFC 8446 §7.1).
@trusted fn tls_expand_label(secret: *u8, label: *u8, ctx: *u8, ctxlen: i64, out: *u8, outlen: i64) {
    var ll: i64 = 0;
    while label[ll] != 0 { ll = ll + 1; }
    var info: *u8 = heap_alloc(10 + ll + ctxlen);
    var b: Bld = Bld { p: info, len: 0 };
    bld_u16(raw b, outlen);
    bld_u8(raw b, 6 + ll);
    bld_bytes(raw b, "tls13 ", 6);
    bld_bytes(raw b, label, ll);
    bld_u8(raw b, ctxlen);
    bld_bytes(raw b, ctx, ctxlen);
    hkdf_expand(2, secret, 32, info, b.len, out, outlen);
    heap_free(info);
}

// Derive-Secret(secret, label, transcript_hash)
fn tls_derive_secret(secret: *u8, label: *u8, thash: *u8, out: *u8) {
    tls_expand_label(secret, label, thash, 32, out, 32);
}

fn tls_key_len(suite: i64) -> i64 {
    if suite == 4865 { ret 16; }
    ret 32;
}

fn tls_traffic_keys(secret: *u8, key: *u8, iv: *u8, suite: i64) {
    tls_expand_label(secret, "key", "", 0, key, tls_key_len(suite));
    tls_expand_label(secret, "iv", "", 0, iv, 12);
}

@trusted fn tls_th_add(t: *Tls, msg: *u8, n: i64) {
    if t.thlen + n > t.thcap {
        var ncap: i64 = (t.thlen + n) * 2;
        var np: *u8 = heap_alloc(ncap);
        raw_copy(np, t.th, t.thlen);
        heap_free(t.th);
        t.th = np;
        t.thcap = ncap;
    }
    raw_copy(t.th + t.thlen, msg, n);
    t.thlen = t.thlen + n;
}

fn tls_th_hash(t: *Tls, out: *u8) { sha256(t.th, t.thlen, out); }

// ---------------------------------------------------------------- records

@trusted fn tls_nonce(iv: *u8, seq: i64, out: *u8) {
    raw_copy(out, iv, 12);
    var i: i64 = 0;
    while i < 8 {
        out[11 - i] = out[11 - i] ^ cast(u8) ((seq >> (i * 8)) & 255);
        i = i + 1;
    }
}

fn tls_seal(t: *Tls, nonce: *u8, aad: *u8, pt: *u8, n: i64, out: *u8) -> i64 {
    if t.suite == 4865 { ret aes128gcm_seal(t.c_key, nonce, aad, 5, pt, n, out); }
    ret chacha20poly1305_seal(t.c_key, nonce, aad, 5, pt, n, out);
}

fn tls_open(t: *Tls, nonce: *u8, aad: *u8, ct: *u8, n: i64, out: *u8) -> i64 {
    if t.suite == 4865 { ret aes128gcm_open(t.s_key, nonce, aad, 5, ct, n, out); }
    ret chacha20poly1305_open(t.s_key, nonce, aad, 5, ct, n, out);
}

@trusted fn tls_send_plain(t: *Tls, rtype: i64, data: *u8, n: i64) -> bool {
    var rec: *u8 = heap_alloc(n + 5);
    rec[0] = cast(u8) rtype; rec[1] = 3; rec[2] = 3;
    if rtype == 22 { rec[2] = 1; }
    rec[3] = cast(u8) (n >> 8); rec[4] = cast(u8) (n & 255);
    raw_copy(rec + 5, data, n);
    var r: i64 = net_write_all(t.fd, rec, n + 5);
    heap_free(rec);
    if r < 0 { ret tls_fail("connection write failed"); }
    ret true;
}

// Encrypts and sends one record (inner content type `itype`).
@trusted fn tls_send_record(t: *Tls, itype: i64, data: *u8, n: i64) -> bool {
    var inner: *u8 = heap_alloc(n + 1);
    raw_copy(inner, data, n);
    inner[n] = cast(u8) itype;
    var clen: i64 = n + 1 + 16;
    var rec: *u8 = heap_alloc(clen + 5);
    rec[0] = 23; rec[1] = 3; rec[2] = 3;
    rec[3] = cast(u8) (clen >> 8); rec[4] = cast(u8) (clen & 255);
    var nonce: *u8 = heap_alloc(12);
    tls_nonce(t.c_iv, t.c_seq, nonce);
    tls_seal(t, nonce, rec, inner, n + 1, rec + 5);
    t.c_seq = t.c_seq + 1;
    var r: i64 = net_write_all(t.fd, rec, clen + 5);
    heap_free(inner); heap_free(rec); heap_free(nonce);
    if r < 0 { ret tls_fail("connection write failed"); }
    ret true;
}

// Reads the next record.  Allocates `*out` (caller frees) holding the
// plaintext; `*rtype` is the (inner) content type.  Plaintext
// change_cipher_spec records are skipped.
@trusted fn tls_read_record(t: *Tls, rtype: *i64, out: *rawptr, outlen: *i64) -> bool {
    var hdr: *u8 = heap_alloc(5);
    var done: bool = false;
    var ok: bool = true;
    while !done {
        if !tls_recv_exact(t.fd, hdr, 5) { ok = tls_fail("connection closed while reading a record"); done = true; }
        else {
            var len: i64 = rd16(hdr + 3);
            if len > 16384 + 256 { ok = tls_fail("record too large"); done = true; }
            else {
                var body: *u8 = heap_alloc(len + 1);
                if !tls_recv_exact(t.fd, body, len) { heap_free(body); ok = tls_fail("connection closed while reading a record"); done = true; }
                else if hdr[0] == 20 { heap_free(body); }
                else if hdr[0] == 23 && t.encrypted == 1 {
                    var nonce: *u8 = heap_alloc(12);
                    tls_nonce(t.s_iv, t.s_seq, nonce);
                    var pt: *u8 = heap_alloc(len);
                    var n: i64 = tls_open(t, nonce, hdr, body, len, pt);
                    heap_free(nonce); heap_free(body);
                    t.s_seq = t.s_seq + 1;
                    if n < 0 { heap_free(pt); ok = tls_fail("bad record MAC"); done = true; }
                    else {
                        while n > 0 && pt[n - 1] == 0 { n = n - 1; }
                        if n == 0 { heap_free(pt); ok = tls_fail("empty inner plaintext"); done = true; }
                        else {
                            *rtype = cast(i64) pt[n - 1];
                            *out = pt;
                            *outlen = n - 1;
                            done = true;
                        }
                    }
                } else if t.encrypted == 0 && (hdr[0] == 22 || hdr[0] == 21) {
                    *rtype = cast(i64) hdr[0];
                    *out = body;
                    *outlen = len;
                    done = true;
                } else { heap_free(body); ok = tls_fail("unexpected record type"); done = true; }
            }
        }
    }
    heap_free(hdr);
    ret ok;
}

// Returns the next whole handshake message (header included) in a fresh
// buffer.  Handshake data may be coalesced or split across records.
@trusted fn tls_next_hs(t: *Tls, mlen: *i64) -> *u8 {
    var ok: bool = true;
    while ok {
        if t.hslen >= 4 {
            var need: i64 = 4 + rd24(t.hs + 1);
            if t.hslen >= need {
                var msg: *u8 = heap_alloc(need);
                raw_copy(msg, t.hs, need);
                raw_move(t.hs, t.hs + need, t.hslen - need);
                t.hslen = t.hslen - need;
                *mlen = need;
                ret msg;
            }
        }
        var rt: i64 = 0;
        var data: rawptr = null;
        var dl: i64 = 0;
        if !tls_read_record(t, raw rt, raw data, raw dl) { ok = false; }
        else if rt == 21 {
            ok = tls_fail(tls_alert_name(dl >= 2, cast(*u8) data));
            heap_free(cast(*u8) data);
        } else if rt != 22 {
            heap_free(cast(*u8) data);
            ok = tls_fail("unexpected record during the handshake");
        } else {
            if t.hslen + dl > t.hscap {
                var ncap: i64 = (t.hslen + dl) * 2;
                var np: *u8 = heap_alloc(ncap);
                raw_copy(np, t.hs, t.hslen);
                heap_free(t.hs);
                t.hs = np;
                t.hscap = ncap;
            }
            raw_copy(t.hs + t.hslen, cast(*u8) data, dl);
            t.hslen = t.hslen + dl;
            heap_free(cast(*u8) data);
        }
    }
    ret null;
}

// ---------------------------------------------------------------- handshake

@trusted fn tls_build_client_hello(host: *u8, random: *u8, sid: *u8, pub: *u8, out: *u8) -> i64 {
    var b: Bld = Bld { p: out, len: 0 };
    var ipbuf: *u8 = heap_alloc(4);
    var use_sni: bool = !x509_parse_ipv4(host, ipbuf);
    heap_free(ipbuf);
    var hl: i64 = 0;
    while host[hl] != 0 { hl = hl + 1; }
    bld_u8(raw b, 1);
    bld_u24(raw b, 0);                  // patched below
    bld_u16(raw b, 771);
    bld_bytes(raw b, random, 32);
    bld_u8(raw b, 32);
    bld_bytes(raw b, sid, 32);
    bld_u16(raw b, 4); bld_u16(raw b, 4867); bld_u16(raw b, 4865);   // CHACHA20_POLY1305, AES_128_GCM
    bld_u8(raw b, 1); bld_u8(raw b, 0);
    var extlen_at: i64 = b.len;
    bld_u16(raw b, 0);
    if use_sni {
        bld_u16(raw b, 0);
        bld_u16(raw b, hl + 5);
        bld_u16(raw b, hl + 3);
        bld_u8(raw b, 0);
        bld_u16(raw b, hl);
        bld_bytes(raw b, host, hl);
    }
    bld_u16(raw b, 10); bld_u16(raw b, 4); bld_u16(raw b, 2); bld_u16(raw b, 29);          // supported_groups: x25519
    bld_u16(raw b, 13); bld_u16(raw b, 18); bld_u16(raw b, 16);                         // signature_algorithms
    bld_u16(raw b, 2052); bld_u16(raw b, 2053); bld_u16(raw b, 2054); bld_u16(raw b, 1027); bld_u16(raw b, 1283);
    bld_u16(raw b, 1025); bld_u16(raw b, 1281); bld_u16(raw b, 1537);
    bld_u16(raw b, 50); bld_u16(raw b, 18); bld_u16(raw b, 16);                         // signature_algorithms_cert
    bld_u16(raw b, 2052); bld_u16(raw b, 2053); bld_u16(raw b, 2054); bld_u16(raw b, 1027); bld_u16(raw b, 1283);
    bld_u16(raw b, 1025); bld_u16(raw b, 1281); bld_u16(raw b, 1537);
    bld_u16(raw b, 43); bld_u16(raw b, 3); bld_u8(raw b, 2); bld_u16(raw b, 772);          // supported_versions: 1.3
    bld_u16(raw b, 51); bld_u16(raw b, 38); bld_u16(raw b, 36); bld_u16(raw b, 29); bld_u16(raw b, 32);
    bld_bytes(raw b, pub, 32);                                                    // key_share
    bld_put16_at(raw b, extlen_at, b.len - extlen_at - 2);
    var body: i64 = b.len - 4;
    out[1] = cast(u8) (body >> 16); out[2] = cast(u8) ((body >> 8) & 255); out[3] = cast(u8) (body & 255);
    ret b.len;
}

// Parses a ServerHello; on success stores the server's x25519 share in `spub`.
@trusted fn tls_parse_server_hello(msg: *u8, n: i64, sid: *u8, spub: *u8, suite: *i64) -> bool {
    if msg[0] != 2 { ret tls_fail("expected ServerHello"); }
    var p: *u8 = msg + 4;
    var len: i64 = n - 4;
    if len < 2 + 32 + 1 { ret tls_fail("truncated ServerHello"); }
    var hrr: *u8 = "cf21ad74e59a6111be1d8c021e65b891c2a211167abb8c5e079e09e2c8a8339c";
    if x509_eq(p + 2, 32, hrr) { ret tls_fail("HelloRetryRequest is not supported"); }
    var off: i64 = 34;
    var sl: i64 = cast(i64) p[off];
    off = off + 1;
    if sl != 32 || off + sl + 2 + 1 + 2 > len { ret tls_fail("bad ServerHello"); }
    if raw_compare(p + off, sid, 32) != 0 { ret tls_fail("ServerHello session id mismatch"); }
    off = off + sl;
    var cs: i64 = rd16(p + off);
    if cs != 4867 && cs != 4865 { ret tls_fail("server chose an unsupported cipher suite"); }
    *suite = cs;
    off = off + 2;
    if p[off] != 0 { ret tls_fail("server selected compression"); }
    off = off + 1;
    var el: i64 = rd16(p + off);
    off = off + 2;
    if off + el != len { ret tls_fail("bad ServerHello extensions"); }
    var got_version: bool = false;
    var got_share: bool = false;
    var end: i64 = off + el;
    while off + 4 <= end {
        var et: i64 = rd16(p + off);
        var ed: i64 = rd16(p + off + 2);
        off = off + 4;
        if off + ed > end { ret tls_fail("bad ServerHello extension"); }
        if et == 43 {
            if ed != 2 || rd16(p + off) != 772 { ret tls_fail("server did not select TLS 1.3"); }
            got_version = true;
        } else if et == 51 {
            if ed != 36 || rd16(p + off) != 29 || rd16(p + off + 2) != 32 { ret tls_fail("unsupported key share group"); }
            raw_copy(spub, p + off + 4, 32);
            got_share = true;
        }
        off = off + ed;
    }
    if !got_version || !got_share { ret tls_fail("ServerHello is missing required extensions"); }
    ret true;
}

// Verifies CertificateVerify with the leaf's public key.
@trusted fn tls_verify_cv(leaf: *Cert, scheme: i64, thash: *u8, sig: *u8, siglen: i64) -> bool {
    var content: *u8 = heap_alloc(64 + 33 + 1 + 32);
    raw_fill(content, 32, 64);
    raw_copy(content + 64, "TLS 1.3, server CertificateVerify", 33);
    content[97] = 0;
    raw_copy(content + 98, thash, 32);
    var ok: bool = false;
    var alg: i64 = 0;
    if scheme == 1027 || scheme == 2052 { alg = 2; }
    else if scheme == 1283 || scheme == 2053 { alg = 3; }
    else if scheme == 2054 { alg = 4; }
    if alg != 0 {
        var hs: i64 = hash_size(alg);
        var dg: *u8 = heap_alloc(hs);
        hash_digest(alg, content, 130, dg);
        if scheme == 1027 && leaf.key_type == 2 && leaf.curve == 1 {
            ok = ecdsa_verify_der(1, leaf.key1, leaf.key1len, dg, hs, sig, siglen);
        } else if scheme == 1283 && leaf.key_type == 2 && leaf.curve == 2 {
            ok = ecdsa_verify_der(2, leaf.key1, leaf.key1len, dg, hs, sig, siglen);
        } else if (scheme == 2052 || scheme == 2053 || scheme == 2054) && leaf.key_type == 1 {
            ok = rsa_verify_pss(leaf.key1, leaf.key1len, leaf.key2, leaf.key2len, alg, dg, hs, sig, siglen);
        }
        heap_free(dg);
    }
    heap_free(content);
    ret ok;
}

@trusted fn tls_free_chain(chain: ^VecPtr) {
    var i: i64 = 0;
    while i < vec_ptr_len(chain) { x509_destroy(vec_ptr_get(chain, i)); i = i + 1; }
    vec_ptr_free(chain);
}

@trusted fn tls_zero_secret(p: *u8, n: i64) { raw_zero(p, n); }

// Runs the TLS 1.3 handshake on a connected socket.  `anchors` is a VecPtr of
// trusted *Cert (see x509_load_system_roots).  Returns null on failure
// (see tls_last_error).  On failure the socket is left open for the caller.
@trusted fn tls_connect(fd: i64, host: *u8, anchors: *VecPtr) -> ^Tls {
    var t: ^Tls = cast(^Tls) heap_alloc(25 * 8);
    raw_zero(t, 25 * 8);
    t.fd = fd;
    t.c_key = heap_alloc(32); t.c_iv = heap_alloc(12); t.s_key = heap_alloc(32); t.s_iv = heap_alloc(12);
    t.c_secret = heap_alloc(32); t.s_secret = heap_alloc(32);
    t.thcap = 4096; t.th = heap_alloc(4096);
    t.hscap = 4096; t.hs = heap_alloc(4096);
    t.rbuf = null;
    if tls_handshake(t, host, anchors) { ret t; }
    tls_free(t);
    ret null;
}

@trusted fn tls_release(t: &mut Tls) {
    tls_zero_secret(t.c_key, 32); tls_zero_secret(t.s_key, 32);
    tls_zero_secret(t.c_secret, 32); tls_zero_secret(t.s_secret, 32);
    heap_free(t.c_key); heap_free(t.c_iv); heap_free(t.s_key); heap_free(t.s_iv);
    heap_free(t.c_secret); heap_free(t.s_secret);
    heap_free(t.th); heap_free(t.hs);
    if t.rbuf != null { heap_free(t.rbuf); }
}

fn tls_free(t: ^Tls) { }

@trusted fn tls_handshake(t: *Tls, host: *u8, anchors: *VecPtr) -> bool {
    var rnd: *u8 = heap_alloc(32 + 32 + 32);
    if random_bytes(rnd, 96) < 0 { ret tls_fail("no randomness available"); }
    var random: *u8 = rnd;
    var sid: *u8 = rnd + 32;
    var priv: *u8 = rnd + 64;
    var pub: *u8 = heap_alloc(32);
    x25519_base(pub, priv);

    var ch: *u8 = heap_alloc(1024);
    var chlen: i64 = tls_build_client_hello(host, random, sid, pub, ch);
    if !tls_send_plain(t, 22, ch, chlen) { ret false; }
    tls_th_add(t, ch, chlen);
    heap_free(ch);
    var ccs: *u8 = heap_alloc(1);
    ccs[0] = 1;
    tls_send_plain(t, 20, ccs, 1);
    heap_free(ccs);

    // ServerHello
    var mlen: i64 = 0;
    var sh: *u8 = tls_next_hs(t, raw mlen);
    if sh == null { ret false; }
    var spub: *u8 = heap_alloc(32);
    if !tls_parse_server_hello(sh, mlen, sid, spub, raw t.suite) { ret false; }
    tls_th_add(t, sh, mlen);
    heap_free(sh);

    var shared: *u8 = heap_alloc(32);
    x25519(shared, priv, spub);
    var nz: i64 = 0;
    var i: i64 = 0;
    while i < 32 { nz = nz | (cast(i64) shared[i]); i = i + 1; }
    if nz == 0 { ret tls_fail("invalid key share"); }

    // key schedule
    var zeros: *u8 = heap_alloc(32);
    raw_zero(zeros, 32);
    var early: *u8 = heap_alloc(32);
    hkdf_extract(2, zeros, 32, zeros, 32, early);
    var empty_hash: *u8 = heap_alloc(32);
    sha256("", 0, empty_hash);
    var derived: *u8 = heap_alloc(32);
    tls_derive_secret(early, "derived", empty_hash, derived);
    var hs_secret: *u8 = heap_alloc(32);
    hkdf_extract(2, derived, 32, shared, 32, hs_secret);
    var th: *u8 = heap_alloc(32);
    tls_th_hash(t, th);
    tls_derive_secret(hs_secret, "c hs traffic", th, t.c_secret);
    tls_derive_secret(hs_secret, "s hs traffic", th, t.s_secret);
    tls_traffic_keys(t.c_secret, t.c_key, t.c_iv, t.suite);
    tls_traffic_keys(t.s_secret, t.s_key, t.s_iv, t.suite);
    t.encrypted = 1;
    t.c_seq = 0; t.s_seq = 0;
    tls_zero_secret(shared, 32); tls_zero_secret(priv, 32);

    // EncryptedExtensions
    var m: *u8 = tls_next_hs(t, raw mlen);
    if m == null { ret false; }
    if m[0] != 8 { ret tls_fail("expected EncryptedExtensions"); }
    tls_th_add(t, m, mlen);
    heap_free(m);

    // Certificate
    m = tls_next_hs(t, raw mlen);
    if m == null { ret false; }
    if m[0] == 13 { ret tls_fail("server requested a client certificate (unsupported)"); }
    if m[0] != 11 { ret tls_fail("expected Certificate"); }
    var chain: ^VecPtr = vec_ptr_new(8);
    var cok: bool = true;
    var off: i64 = 4;
    var ctxl: i64 = cast(i64) m[off];
    off = off + 1 + ctxl;
    if off + 3 > mlen { cok = tls_fail("truncated Certificate"); }
    else {
        var listlen: i64 = rd24(m + off);
        off = off + 3;
        var end: i64 = off + listlen;
        if end != mlen { cok = tls_fail("bad Certificate length"); }
        while cok && off < end {
            if off + 3 > end { cok = tls_fail("truncated Certificate"); }
            else {
                var cl: i64 = rd24(m + off);
                off = off + 3;
                if off + cl + 2 > end { cok = tls_fail("truncated Certificate"); }
                else {
                    var c: ^Cert = x509_parse(m + off, cl);
                    if c == null { cok = tls_fail("unsupported or malformed server certificate"); }
                    else { vec_ptr_push(chain, cast(rawptr) c); }
                    off = off + cl;
                    var xl: i64 = rd16(m + off);
                    off = off + 2 + xl;
                }
            }
        }
    }
    if !cok { ret false; }
    if vec_ptr_len(chain) == 0 { ret tls_fail("server sent no certificate"); }
    var verr: i64 = x509_verify_chain(chain, anchors, host, time_unix());
    if verr != 0 { TLS_ERR = x509_strerror(verr); ret false; }
    tls_th_add(t, m, mlen);
    heap_free(m);
    var leaf: *Cert = vec_ptr_get(chain, 0);

    // CertificateVerify (signature covers the transcript up to the Certificate)
    tls_th_hash(t, th);
    m = tls_next_hs(t, raw mlen);
    if m == null { ret false; }
    if m[0] != 15 || mlen < 8 { ret tls_fail("expected CertificateVerify"); }
    var scheme: i64 = rd16(m + 4);
    var sl: i64 = rd16(m + 6);
    if 8 + sl != mlen { ret tls_fail("bad CertificateVerify"); }
    if !tls_verify_cv(leaf, scheme, th, m + 8, sl) { ret tls_fail("invalid CertificateVerify signature"); }
    tls_th_add(t, m, mlen);
    heap_free(m);
    tls_free_chain(chain);

    // server Finished
    tls_th_hash(t, th);
    var fkey: *u8 = heap_alloc(32);
    tls_expand_label(t.s_secret, "finished", "", 0, fkey, 32);
    var expect: *u8 = heap_alloc(32);
    hmac(2, fkey, 32, th, 32, expect);
    m = tls_next_hs(t, raw mlen);
    if m == null { ret false; }
    if m[0] != 20 || mlen != 36 { ret tls_fail("expected Finished"); }
    if !ct_equal(expect, m + 4, 32) { ret tls_fail("bad Finished MAC"); }
    tls_th_add(t, m, mlen);
    heap_free(m);

    // application secrets cover the transcript through the server Finished
    tls_th_hash(t, th);
    tls_derive_secret(hs_secret, "derived", empty_hash, derived);
    var master: *u8 = heap_alloc(32);
    hkdf_extract(2, derived, 32, zeros, 32, master);
    var c_ap: *u8 = heap_alloc(32);
    var s_ap: *u8 = heap_alloc(32);
    tls_derive_secret(master, "c ap traffic", th, c_ap);
    tls_derive_secret(master, "s ap traffic", th, s_ap);

    // client Finished under the handshake keys
    tls_expand_label(t.c_secret, "finished", "", 0, fkey, 32);
    var fin: *u8 = heap_alloc(36);
    fin[0] = 20; fin[1] = 0; fin[2] = 0; fin[3] = 32;
    hmac(2, fkey, 32, th, 32, fin + 4);
    if !tls_send_record(t, 22, fin, 36) { ret false; }

    raw_copy(t.c_secret, c_ap, 32);
    raw_copy(t.s_secret, s_ap, 32);
    tls_traffic_keys(t.c_secret, t.c_key, t.c_iv, t.suite);
    tls_traffic_keys(t.s_secret, t.s_key, t.s_iv, t.suite);
    t.c_seq = 0; t.s_seq = 0;
    tls_zero_secret(hs_secret, 32); tls_zero_secret(master, 32); tls_zero_secret(c_ap, 32); tls_zero_secret(s_ap, 32);
    heap_free(rnd); heap_free(pub); heap_free(spub); heap_free(shared); heap_free(zeros); heap_free(early);
    heap_free(empty_hash); heap_free(derived); heap_free(hs_secret); heap_free(th); heap_free(fkey);
    heap_free(expect); heap_free(master); heap_free(c_ap); heap_free(s_ap); heap_free(fin);
    ret true;
}

// ---------------------------------------------------------------- application data

@trusted fn tls_key_update(secret: *u8, key: *u8, iv: *u8, suite: i64) {
    var ns: *u8 = heap_alloc(32);
    tls_expand_label(secret, "traffic upd", "", 0, ns, 32);
    raw_copy(secret, ns, 32);
    tls_zero_secret(ns, 32);
    heap_free(ns);
    tls_traffic_keys(secret, key, iv, suite);
}

@trusted fn tls_alert_name(have: bool, p: *u8) -> *u8 {
    if !have { ret "malformed alert"; }
    var d: i64 = cast(i64) p[1];
    if d == 10 { ret "server alert: unexpected_message"; }
    if d == 20 { ret "server alert: bad_record_mac"; }
    if d == 40 { ret "server alert: handshake_failure"; }
    if d == 42 { ret "server alert: bad_certificate"; }
    if d == 47 { ret "server alert: illegal_parameter"; }
    if d == 48 { ret "server alert: unknown_ca"; }
    if d == 50 { ret "server alert: decode_error"; }
    if d == 51 { ret "server alert: decrypt_error"; }
    if d == 70 { ret "server alert: protocol_version"; }
    if d == 80 { ret "server alert: internal_error"; }
    if d == 109 { ret "server alert: missing_extension"; }
    ret "server alert";
}

// Sends `n` bytes; returns n, or a negative value on error.
@trusted fn tls_write(t: *Tls, buf: *u8, n: i64) -> i64 {
    if t.failed == 1 { ret -1; }
    var done: i64 = 0;
    while done < n {
        var chunk: i64 = n - done;
        if chunk > 16384 { chunk = 16384; }
        if !tls_send_record(t, 23, buf + done, chunk) { t.failed = 1; ret -1; }
        done = done + chunk;
    }
    ret n;
}

// Reads up to `cap` bytes.  Returns 0 at end of stream (close_notify or
// closed connection), a negative value on error.
@trusted fn tls_read(t: *Tls, buf: *u8, cap: i64) -> i64 {
    while t.rbuf == null || t.rpos >= t.rlen {
        if t.rbuf != null { heap_free(t.rbuf); t.rbuf = null; }
        if t.eof == 1 { ret 0; }
        if t.failed == 1 { ret -1; }
        var rt: i64 = 0;
        var data: rawptr = null;
        var dl: i64 = 0;
        if !tls_read_record(t, raw rt, raw data, raw dl) { t.failed = 1; ret -1; }
        var p: *u8 = cast(*u8) data;
        if rt == 23 {
            t.rbuf = p; t.rpos = 0; t.rlen = dl;
        } else if rt == 21 {
            if dl >= 2 && p[1] == 0 { t.eof = 1; }
            else { t.failed = 1; TLS_ERR = tls_alert_name(dl >= 2, p); }
            heap_free(p);
        } else if rt == 22 {
            // post-handshake: NewSessionTicket is ignored, KeyUpdate honoured
            var off: i64 = 0;
            while off + 4 <= dl {
                var mt: i64 = cast(i64) p[off];
                var ml: i64 = rd24(p + off + 1);
                if off + 4 + ml > dl { off = dl; }
                else {
                    if mt == 24 && ml == 1 {
                        tls_key_update(t.s_secret, t.s_key, t.s_iv, t.suite);
                        t.s_seq = 0;
                        if p[off + 4] == 1 {
                            var ku: *u8 = heap_alloc(5);
                            ku[0] = 24; ku[1] = 0; ku[2] = 0; ku[3] = 1; ku[4] = 0;
                            tls_send_record(t, 22, ku, 5);
                            heap_free(ku);
                            tls_key_update(t.c_secret, t.c_key, t.c_iv, t.suite);
                            t.c_seq = 0;
                        }
                    }
                    off = off + 4 + ml;
                }
            }
            heap_free(p);
        } else {
            heap_free(p);
            t.failed = 1;
            TLS_ERR = "unexpected record type";
        }
    }
    var n: i64 = t.rlen - t.rpos;
    if n > cap { n = cap; }
    raw_copy(buf, t.rbuf + t.rpos, n);
    t.rpos = t.rpos + n;
    ret n;
}

// Sends close_notify.  Does not close the socket.
@trusted fn tls_close(t: ^Tls) {
    if t.failed == 0 {
        var al: *u8 = heap_alloc(2);
        al[0] = 1; al[1] = 0;
        tls_send_record(t, 21, al, 2);
        heap_free(al);
    }
    tls_free(t);
}

std/vec.mw:
@no_main

@import("mem.mw")

@drop(vec_ptr_release)
struct VecPtr {
    data: rawptr;
    len: i64;
    cap: i64;
}

// The vector owns its buffer: dropping the `^VecPtr` frees both.
@trusted fn vec_ptr_new(initial_cap: i64) -> ^VecPtr {
    var v: ^VecPtr = cast(^VecPtr) alloc(24);
    if (initial_cap < 4) {
        initial_cap = 4;
    }
    v.data = alloc(initial_cap * 8);
    v.len = 0;
    v.cap = initial_cap;
    ret v;
}

@trusted fn vec_ptr_push(v: *VecPtr, item: rawptr) {
    if (v.len >= v.cap) {
        var new_cap: i64 = v.cap * 2;
        v.data = realloc(v.data, new_cap * 8);
        v.cap = new_cap;
    }

    var slot: *rawptr = v.data + (v.len * 8);
    *slot = item;

    v.len = v.len + 1;
}

@trusted fn vec_ptr_get(v: *VecPtr, index: i64) -> rawptr {
    if (index < 0) { ret 0; }
    if (index >= v.len) { ret 0; }

    var slot: *rawptr = v.data + (index * 8);
    ret *slot;
}

// Run by the drop: frees the buffer, then the struct itself is freed.
@trusted fn vec_ptr_release(v: &mut VecPtr) {
    dealloc(v.data);
}

// Frees a vector: it takes the owner, which is dropped here.
fn vec_ptr_free(v: ^VecPtr) { }

// Frees a vector that is only known by a plain pointer (a field, a global): the caller was its owner.
@unsafe fn vec_ptr_destroy(v: *VecPtr) { vec_ptr_free(cast(^VecPtr) v); }

@trusted fn vec_ptr_set(vec: *VecPtr, index: i64, value: rawptr) {
    if (vec == 0) { ret; }
    if (index < 0 || index >= vec.len) { ret; }

    var target: *rawptr = cast(*rawptr) (cast(i64) vec.data + (index * 8));
    *target = value;
}

@drop(vec_i64_release)
struct VecI64 {
    data: rawptr;
    len: i64;
    cap: i64;
}

@trusted fn vec_i64_new(initial_cap: i64) -> ^VecI64 {
    var v: ^VecI64 = cast(^VecI64) alloc(24);
    if (initial_cap < 4) {
        initial_cap = 4;
    }
    v.data = alloc(initial_cap * 8);
    v.len = 0;
    v.cap = initial_cap;
    ret v;
}

@trusted fn vec_i64_push(v: *VecI64, val: i64) {
    if (v.len >= v.cap) {
        var new_cap: i64 = v.cap * 2;
        v.data = realloc(v.data, new_cap * 8);
        v.cap = new_cap;
    }

    var slot: *i64 = v.data + (v.len * 8);
    *slot = val;

    v.len = v.len + 1;
}

@trusted fn vec_i64_get(v: *VecI64, index: i64) -> i64 {
    if (index < 0) { ret 0; }
    if (index >= v.len) { ret 0; }

    var slot: *i64 = v.data + (index * 8);
    ret *slot;
}

@trusted fn vec_i64_release(v: &mut VecI64) {
    dealloc(v.data);
}

fn vec_i64_free(v: ^VecI64) { }

@unsafe fn vec_i64_destroy(v: *VecI64) { vec_i64_free(cast(^VecI64) v); }

@trusted fn vec_i64_set(v: *VecI64, index: i64, val: i64) {
    if (index < 0 || index >= v.len) { ret; }
    var slot: *i64 = v.data + (index * 8);
    *slot = val;
}

fn vec_ptr_len(v: *VecPtr) -> i64 {
    ret v.len;
}

fn vec_i64_len(v: *VecI64) -> i64 {
    ret v.len;
}

// Removes and returns the last element (0 when empty).
fn vec_ptr_pop(v: *VecPtr) -> rawptr {
    if (v.len == 0) { ret 0; }
    v.len = v.len - 1;
    ret vec_ptr_get(v, v.len);
}

fn vec_i64_pop(v: *VecI64) -> i64 {
    if (v.len == 0) { ret 0; }
    v.len = v.len - 1;
    ret vec_i64_get(v, v.len);
}

// In-place ascending sort (heap sort: no recursion, no extra memory).
fn vec_i64_sort(v: *VecI64) {
    var n: i64 = v.len;
    var start: i64 = n / 2 - 1;
    while start >= 0 {
        vec_i64_sift(v, start, n);
        start = start - 1;
    }
    var end: i64 = n - 1;
    while end > 0 {
        var t: i64 = vec_i64_get(v, 0);
        vec_i64_set(v, 0, vec_i64_get(v, end));
        vec_i64_set(v, end, t);
        vec_i64_sift(v, 0, end);
        end = end - 1;
    }
}

fn vec_i64_sift(v: *VecI64, root: i64, n: i64) {
    while 1 == 1 {
        var child: i64 = root * 2 + 1;
        if child >= n {
            ret;
        }
        if child + 1 < n && vec_i64_get(v, child) < vec_i64_get(v, child + 1) {
            child = child + 1;
        }
        if vec_i64_get(v, root) >= vec_i64_get(v, child) {
            ret;
        }
        var t: i64 = vec_i64_get(v, root);
        vec_i64_set(v, root, vec_i64_get(v, child));
        vec_i64_set(v, child, t);
        root = child;
    }
}

std/x25519.mw:
@no_main

@import("raw.mw")
@import("heap.mw")

// X25519 (RFC 7748) over GF(2^255-19), after TweetNaCl: field elements are
// 16 limbs of 16 bits held in i64, which needs no 128-bit arithmetic.

@trusted fn gf_new() -> *i64 {
    var g: *i64 = cast(*i64) heap_alloc(16 * 8);
    raw_zero(cast(*u8) g, 128);
    ret g;
}

@trusted fn gf_car(o: *i64) {
    var i: i64 = 0;
    while i < 16 {
        o[i] = o[i] + 65536;
        var c: i64 = o[i] >> 16;
        if i < 15 { o[i + 1] = o[i + 1] + c - 1; }
        else { o[0] = o[0] + (c - 1) + 37 * (c - 1); }
        o[i] = o[i] - (c << 16);
        i = i + 1;
    }
}

@trusted fn gf_sel(p: *i64, q: *i64, b: i64) {
    var c: i64 = ~(b - 1);
    var i: i64 = 0;
    while i < 16 {
        var t: i64 = c & (p[i] ^ q[i]);
        p[i] = p[i] ^ t;
        q[i] = q[i] ^ t;
        i = i + 1;
    }
}

@trusted fn gf_pack(o: *u8, n: *i64) {
    var t: *i64 = gf_new();
    var m: *i64 = gf_new();
    var i: i64 = 0;
    while i < 16 { t[i] = n[i]; i = i + 1; }
    gf_car(t); gf_car(t); gf_car(t);
    var j: i64 = 0;
    while j < 2 {
        m[0] = t[0] - 65517;
        i = 1;
        while i < 15 {
            m[i] = t[i] - 65535 - ((m[i - 1] >> 16) & 1);
            m[i - 1] = m[i - 1] & 65535;
            i = i + 1;
        }
        m[15] = t[15] - 32767 - ((m[14] >> 16) & 1);
        var b: i64 = (m[15] >> 16) & 1;
        m[14] = m[14] & 65535;
        gf_sel(t, m, 1 - b);
        j = j + 1;
    }
    i = 0;
    while i < 16 {
        o[2 * i] = cast(u8) (t[i] & 255);
        o[2 * i + 1] = cast(u8) (t[i] >> 8);
        i = i + 1;
    }
    heap_free(t); heap_free(m);
}

@trusted fn gf_unpack(o: *i64, n: *u8) {
    var i: i64 = 0;
    while i < 16 { o[i] = (cast(i64) n[2 * i]) + ((cast(i64) n[2 * i + 1]) << 8); i = i + 1; }
    o[15] = o[15] & 32767;
}

@trusted fn gf_add(o: *i64, a: *i64, b: *i64) { var i: i64 = 0; while i < 16 { o[i] = a[i] + b[i]; i = i + 1; } }
@trusted fn gf_sub(o: *i64, a: *i64, b: *i64) { var i: i64 = 0; while i < 16 { o[i] = a[i] - b[i]; i = i + 1; } }

@trusted fn gf_mul(o: *i64, a: *i64, b: *i64) {
    var t: *i64 = cast(*i64) heap_alloc(32 * 8);
    raw_zero(cast(*u8) t, 256);
    var i: i64 = 0;
    while i < 16 {
        var j: i64 = 0;
        var ai: i64 = a[i];
        while j < 16 { t[i + j] = t[i + j] + ai * b[j]; j = j + 1; }
        i = i + 1;
    }
    i = 0;
    while i < 15 { t[i] = t[i] + 38 * t[i + 16]; i = i + 1; }
    i = 0;
    while i < 16 { o[i] = t[i]; i = i + 1; }
    gf_car(o); gf_car(o);
    heap_free(t);
}

@trusted fn gf_inv(o: *i64, inp: *i64) {
    var c: *i64 = gf_new();
    var i: i64 = 0;
    while i < 16 { c[i] = inp[i]; i = i + 1; }
    var a: i64 = 253;
    while a >= 0 {
        gf_mul(c, c, c);
        if a != 2 && a != 4 { gf_mul(c, c, inp); }
        a = a - 1;
    }
    i = 0;
    while i < 16 { o[i] = c[i]; i = i + 1; }
    heap_free(c);
}

// out = scalar * point (all 32 bytes, little endian).
@trusted fn x25519(out: *u8, scalar: *u8, point: *u8) {
    var z: *u8 = heap_alloc(32);
    raw_copy(z, scalar, 32);
    z[31] = (z[31] & 127) | 64;
    z[0] = z[0] & 248;
    var x: *i64 = gf_new();
    var a: *i64 = gf_new(); var b: *i64 = gf_new(); var c: *i64 = gf_new(); var d: *i64 = gf_new();
    var e: *i64 = gf_new(); var f: *i64 = gf_new(); var k: *i64 = gf_new();
    gf_unpack(x, point);
    var i: i64 = 0;
    while i < 16 { b[i] = x[i]; i = i + 1; }
    a[0] = 1; d[0] = 1;
    k[0] = 56129; k[1] = 1;
    i = 254;
    while i >= 0 {
        var r: i64 = ((cast(i64) z[i >> 3]) >> (i & 7)) & 1;
        gf_sel(a, b, r); gf_sel(c, d, r);
        gf_add(e, a, c); gf_sub(a, a, c); gf_add(c, b, d); gf_sub(b, b, d);
        gf_mul(d, e, e); gf_mul(f, a, a); gf_mul(a, c, a); gf_mul(c, b, e);
        gf_add(e, a, c); gf_sub(a, a, c); gf_mul(b, a, a); gf_sub(c, d, f);
        gf_mul(a, c, k); gf_add(a, a, d); gf_mul(c, c, a); gf_mul(a, d, f);
        gf_mul(d, b, x); gf_mul(b, e, e);
        gf_sel(a, b, r); gf_sel(c, d, r);
        i = i - 1;
    }
    gf_inv(c, c);
    gf_mul(a, a, c);
    gf_pack(out, a);
    heap_free(z); heap_free(x); heap_free(a); heap_free(b); heap_free(c);
    heap_free(d); heap_free(e); heap_free(f); heap_free(k);
}

// Public key for a 32-byte secret (scalar * basepoint 9).
@trusted fn x25519_base(out: *u8, scalar: *u8) {
    var nine: *u8 = heap_alloc(32);
    raw_zero(nine, 32);
    nine[0] = 9;
    x25519(out, scalar, nine);
    heap_free(nine);
}

std/x509.mw:
@no_main

@import("raw.mw")
@import("heap.mw")
@import("vec.mw")
@import("hash.mw")
@import("asn1.mw")
@import("rsa.mw")
@import("ecdsa.mw")
@import("encoding.mw")
@import("time.mw")
@import("fs.mw")
@import("env.mw")

// X.509 certificates (RFC 5280): parsing, hostname matching, chain building
// checks and a PEM trust store.  Supported: RSA (PKCS#1 v1.5) and ECDSA
// (P-256 / P-384) signatures with SHA-1/256/384/512, and the extensions
// basicConstraints, keyUsage, extKeyUsage and subjectAltName.  Unknown
// *critical* extensions make a certificate unacceptable.

var X509_KEY_RSA: i64 = 1;
var X509_KEY_EC: i64 = 2;

var X509_OK: i64 = 0;
var X509_E_EMPTY: i64 = 1;
var X509_E_VALIDITY: i64 = 2;
var X509_E_SIGNATURE: i64 = 3;
var X509_E_ISSUER: i64 = 4;
var X509_E_UNTRUSTED: i64 = 5;
var X509_E_HOSTNAME: i64 = 6;
var X509_E_NOT_CA: i64 = 7;
var X509_E_PATHLEN: i64 = 8;
var X509_E_USAGE: i64 = 9;

@drop(x509_release)
struct Cert {
    der: *u8;
    derlen: i64;
    tbs: *u8;
    tbslen: i64;
    issuer: *u8;
    issuerlen: i64;
    subject: *u8;
    subjectlen: i64;
    not_before: i64;
    not_after: i64;
    key_type: i64;
    curve: i64;
    key1: *u8;
    key1len: i64;
    key2: *u8;
    key2len: i64;
    sig_scheme: i64;
    sig_hash: i64;
    sig: *u8;
    siglen: i64;
    has_bc: i64;
    is_ca: i64;
    pathlen: i64;
    has_ku: i64;
    ku: i64;
    has_eku: i64;
    eku_ok: i64;
    san: *u8;
    sanlen: i64;
}

fn x509_strerror(code: i64) -> *u8 {
    if code == 0 { ret "ok"; }
    if code == 1 { ret "empty certificate chain"; }
    if code == 2 { ret "certificate is expired or not yet valid"; }
    if code == 3 { ret "invalid certificate signature"; }
    if code == 4 { ret "certificate issuer does not match"; }
    if code == 5 { ret "unable to get local issuer certificate (untrusted root)"; }
    if code == 6 { ret "certificate is not valid for this host name"; }
    if code == 7 { ret "issuer is not a certificate authority"; }
    if code == 8 { ret "path length constraint exceeded"; }
    if code == 9 { ret "certificate not allowed for server authentication"; }
    ret "unknown certificate error";
}

fn x509_hexval(c: u8) -> i64 {
    var v: i64 = cast(i64) c;
    if v >= 97 { ret v - 87; }
    ret v - 48;
}

// Does the byte window equal the bytes spelled by the lowercase hex string?
@trusted fn x509_eq(p: *u8, len: i64, hex: *u8) -> bool {
    var i: i64 = 0;
    while hex[i] != 0 { i = i + 1; }
    if i != len * 2 { ret false; }
    var k: i64 = 0;
    while k < len {
        if p[k] != cast(u8) ((x509_hexval(hex[k * 2]) << 4) | x509_hexval(hex[k * 2 + 1])) { ret false; }
        k = k + 1;
    }
    ret true;
}

fn x509_bytes_eq(a: *u8, alen: i64, b: *u8, blen: i64) -> bool {
    if alen != blen { ret false; }
    ret raw_compare(a, b, alen) == 0;
}

@trusted fn x509_digits(p: *u8, n: i64) -> i64 {
    var v: i64 = 0;
    var i: i64 = 0;
    while i < n {
        var c: i64 = cast(i64) p[i];
        if c < 48 || c > 57 { ret -1; }
        v = v * 10 + (c - 48);
        i = i + 1;
    }
    ret v;
}

// UTCTime (tag 23) or GeneralizedTime (tag 24) in Zulu to a Unix timestamp; -1 on error.
@trusted fn x509_time(p: *u8, len: i64, tag: i64) -> i64 {
    var year: i64 = 0;
    var off: i64 = 0;
    if tag == 23 {
        if len != 13 { ret -1; }
        var yy: i64 = x509_digits(p, 2);
        if yy < 0 { ret -1; }
        year = 2000 + yy;
        if yy >= 50 { year = 1900 + yy; }
        off = 2;
    } else if tag == 24 {
        if len != 15 { ret -1; }
        year = x509_digits(p, 4);
        if year < 0 { ret -1; }
        off = 4;
    } else { ret -1; }
    if p[len - 1] != 90 { ret -1; }
    var mo: i64 = x509_digits(p + off, 2);
    var d: i64 = x509_digits(p + off + 2, 2);
    var h: i64 = x509_digits(p + off + 4, 2);
    var mi: i64 = x509_digits(p + off + 6, 2);
    var s: i64 = x509_digits(p + off + 8, 2);
    if mo < 1 || mo > 12 || d < 1 || d > 31 || h < 0 || h > 23 || mi < 0 || mi > 59 || s < 0 || s > 60 { ret -1; }
    ret days_from_civil(year, mo, d) * 86400 + h * 3600 + mi * 60 + s;
}

@trusted fn x509_release(c: &mut Cert) {
    heap_free(c.der);
}

// Frees a certificate: it takes the owner, which is dropped here.
fn x509_free(c: ^Cert) { }

@unsafe fn x509_destroy(c: *Cert) { x509_free(cast(^Cert) c); }

// Maps a signatureAlgorithm OID to (scheme, hash); returns false if unsupported.
fn x509_sigalg(oid: *u8, len: i64, c: *Cert) -> bool {
    c.sig_scheme = 0;
    if x509_eq(oid, len, "2a864886f70d010105") { c.sig_scheme = 1; c.sig_hash = 1; }
    else if x509_eq(oid, len, "2a864886f70d01010b") { c.sig_scheme = 1; c.sig_hash = 2; }
    else if x509_eq(oid, len, "2a864886f70d01010c") { c.sig_scheme = 1; c.sig_hash = 3; }
    else if x509_eq(oid, len, "2a864886f70d01010d") { c.sig_scheme = 1; c.sig_hash = 4; }
    else if x509_eq(oid, len, "2a8648ce3d040401") { c.sig_scheme = 2; c.sig_hash = 1; }
    else if x509_eq(oid, len, "2a8648ce3d0401") { c.sig_scheme = 2; c.sig_hash = 1; }
    else if x509_eq(oid, len, "2a8648ce3d040302") { c.sig_scheme = 2; c.sig_hash = 2; }
    else if x509_eq(oid, len, "2a8648ce3d040303") { c.sig_scheme = 2; c.sig_hash = 3; }
    else if x509_eq(oid, len, "2a8648ce3d040304") { c.sig_scheme = 2; c.sig_hash = 4; }
    ret c.sig_scheme != 0;
}

// Parses the extensions SEQUENCE content.  Returns false on malformed input or
// an unknown critical extension.
@trusted fn x509_parse_extensions(c: *Cert, body: *u8, blen: i64) -> bool {
    var exts: Der = Der { p: body, len: blen, pos: 0 };
    while !der_done(raw exts) {
        var ev: rawptr = null; var el: i64 = 0;
        if !der_next(raw exts, 48, raw ev, raw el) { ret false; }
        var e: Der = Der { p: cast(*u8) ev, len: el, pos: 0 };
        var ov: rawptr = null; var ol: i64 = 0;
        if !der_next(raw e, 6, raw ov, raw ol) { ret false; }
        var critical: bool = false;
        if der_peek(raw e) == 1 {
            var bv: rawptr = null; var bl: i64 = 0;
            if !der_next(raw e, 1, raw bv, raw bl) || bl != 1 { ret false; }
            var bb: *u8 = cast(*u8) bv;
            critical = bb[0] != 0;
        }
        var xv: rawptr = null; var xl: i64 = 0;
        if !der_next(raw e, 4, raw xv, raw xl) || !der_done(raw e) { ret false; }
        var oid: *u8 = cast(*u8) ov;
        var val: *u8 = cast(*u8) xv;
        var known: bool = false;
        if x509_eq(oid, ol, "551d13") {
            known = true;
            c.has_bc = 1;
            var bc: Der = Der { p: val, len: xl, pos: 0 };
            var sv: rawptr = null; var sl: i64 = 0;
            if !der_next(raw bc, 48, raw sv, raw sl) { ret false; }
            var inner: Der = Der { p: cast(*u8) sv, len: sl, pos: 0 };
            if der_peek(raw inner) == 1 {
                var cv: rawptr = null; var cl: i64 = 0;
                if !der_next(raw inner, 1, raw cv, raw cl) || cl != 1 { ret false; }
                var cb: *u8 = cast(*u8) cv;
                if cb[0] != 0 { c.is_ca = 1; }
            }
            if der_peek(raw inner) == 2 {
                var pv: rawptr = null; var pl: i64 = 0;
                if !der_next(raw inner, 2, raw pv, raw pl) || pl < 1 || pl > 2 { ret false; }
                var pb: *u8 = cast(*u8) pv;
                c.pathlen = cast(i64) pb[pl - 1];
            }
        } else if x509_eq(oid, ol, "551d0f") {
            known = true;
            c.has_ku = 1;
            var ku: Der = Der { p: val, len: xl, pos: 0 };
            var kv: rawptr = null; var kl: i64 = 0;
            if !der_next(raw ku, 3, raw kv, raw kl) || kl < 2 { ret false; }
            var kb: *u8 = cast(*u8) kv;
            c.ku = cast(i64) kb[1];
        } else if x509_eq(oid, ol, "551d25") {
            known = true;
            c.has_eku = 1;
            var eku: Der = Der { p: val, len: xl, pos: 0 };
            var lv: rawptr = null; var ll: i64 = 0;
            if !der_next(raw eku, 48, raw lv, raw ll) { ret false; }
            var list: Der = Der { p: cast(*u8) lv, len: ll, pos: 0 };
            while !der_done(raw list) {
                var uv: rawptr = null; var ul: i64 = 0;
                if !der_next(raw list, 6, raw uv, raw ul) { ret false; }
                var up: *u8 = cast(*u8) uv;
                if x509_eq(up, ul, "2b06010505070301") || x509_eq(up, ul, "551d2500") { c.eku_ok = 1; }
            }
        } else if x509_eq(oid, ol, "551d11") {
            known = true;
            var sn: Der = Der { p: val, len: xl, pos: 0 };
            var nv: rawptr = null; var nl: i64 = 0;
            if !der_next(raw sn, 48, raw nv, raw nl) { ret false; }
            c.san = cast(*u8) nv;
            c.sanlen = nl;
        } else if x509_eq(oid, ol, "551d0e") || x509_eq(oid, ol, "551d23") || x509_eq(oid, ol, "551d20")
            || x509_eq(oid, ol, "551d1f") || x509_eq(oid, ol, "2b06010505070101") || x509_eq(oid, ol, "551d36") {
            // SKI, AKI, certificatePolicies, CRL distribution points, AIA, inhibitAnyPolicy
            known = true;
        }
        if critical && !known { ret false; }
    }
    ret true;
}

// Parses a DER certificate (the bytes are copied).  Returns null if the
// certificate is malformed or uses unsupported algorithms/critical extensions.
@trusted fn x509_parse(der: *u8, derlen: i64) -> ^Cert {
    var c: ^Cert = cast(^Cert) heap_alloc(sizeof_cert());
    raw_zero(c, sizeof_cert());
    c.der = heap_alloc(derlen);
    raw_copy(c.der, der, derlen);
    c.derlen = derlen;
    c.pathlen = -1;
    if !x509_parse_inner(c) { x509_free(c); ret null; }
    ret c;
}

fn sizeof_cert() -> i64 { ret 29 * 8; }

@trusted fn x509_parse_inner(c: *Cert) -> bool {
    var top: Der = Der { p: c.der, len: c.derlen, pos: 0 };
    var cv: rawptr = null; var cl: i64 = 0;
    if !der_next(raw top, 48, raw cv, raw cl) || !der_done(raw top) { ret false; }
    var cert: Der = Der { p: cast(*u8) cv, len: cl, pos: 0 };
    var tag: i64 = 0; var tv: rawptr = null; var tl: i64 = 0; var all: rawptr = null; var al: i64 = 0;
    // tbsCertificate (kept whole: it is what the signature covers)
    if !der_next_any(raw cert, raw tag, raw tv, raw tl, raw all, raw al) || tag != 48 { ret false; }
    c.tbs = cast(*u8) all;
    c.tbslen = al;
    // signatureAlgorithm
    var sav: rawptr = null; var sal: i64 = 0;
    if !der_next(raw cert, 48, raw sav, raw sal) { ret false; }
    var sa: Der = Der { p: cast(*u8) sav, len: sal, pos: 0 };
    var so: rawptr = null; var sol: i64 = 0;
    if !der_next(raw sa, 6, raw so, raw sol) { ret false; }
    if !x509_sigalg(cast(*u8) so, sol, c) { ret false; }
    // signatureValue
    var sgv: rawptr = null; var sgl: i64 = 0;
    if !der_next(raw cert, 3, raw sgv, raw sgl) || !der_done(raw cert) || sgl < 2 { ret false; }
    var sgb: *u8 = cast(*u8) sgv;
    if sgb[0] != 0 { ret false; }
    c.sig = sgb + 1;
    c.siglen = sgl - 1;
    // tbs contents
    var tbs: Der = Der { p: cast(*u8) tv, len: tl, pos: 0 };
    if der_peek(raw tbs) == 160 {
        var vv: rawptr = null; var vl: i64 = 0;
        if !der_next(raw tbs, 160, raw vv, raw vl) { ret false; }
        var ver: Der = Der { p: cast(*u8) vv, len: vl, pos: 0 };
        var iv: rawptr = null; var il: i64 = 0;
        if !der_next(raw ver, 2, raw iv, raw il) || il != 1 { ret false; }
        var vb: *u8 = cast(*u8) iv;
        if vb[0] != 2 { ret false; }
    }
    var snv: rawptr = null; var snl: i64 = 0;
    if !der_next(raw tbs, 2, raw snv, raw snl) { ret false; }
    var isa: rawptr = null; var isl: i64 = 0;
    if !der_next(raw tbs, 48, raw isa, raw isl) { ret false; }
    // issuer Name, kept as a full TLV
    if !der_next_any(raw tbs, raw tag, raw tv, raw tl, raw all, raw al) || tag != 48 { ret false; }
    c.issuer = cast(*u8) all;
    c.issuerlen = al;
    // validity
    var vav: rawptr = null; var val_: i64 = 0;
    if !der_next(raw tbs, 48, raw vav, raw val_) { ret false; }
    var valid: Der = Der { p: cast(*u8) vav, len: val_, pos: 0 };
    var t1: i64 = 0; var t2: i64 = 0;
    if !der_next_any(raw valid, raw t1, raw tv, raw tl, raw all, raw al) { ret false; }
    c.not_before = x509_time(cast(*u8) tv, tl, t1);
    if !der_next_any(raw valid, raw t2, raw tv, raw tl, raw all, raw al) { ret false; }
    c.not_after = x509_time(cast(*u8) tv, tl, t2);
    if c.not_before < 0 || c.not_after < 0 || !der_done(raw valid) { ret false; }
    // subject Name
    if !der_next_any(raw tbs, raw tag, raw tv, raw tl, raw all, raw al) || tag != 48 { ret false; }
    c.subject = cast(*u8) all;
    c.subjectlen = al;
    // subjectPublicKeyInfo
    var spv: rawptr = null; var spl: i64 = 0;
    if !der_next(raw tbs, 48, raw spv, raw spl) { ret false; }
    var spki: Der = Der { p: cast(*u8) spv, len: spl, pos: 0 };
    var av: rawptr = null; var alen: i64 = 0;
    if !der_next(raw spki, 48, raw av, raw alen) { ret false; }
    var kv: rawptr = null; var kl: i64 = 0;
    if !der_next(raw spki, 3, raw kv, raw kl) || !der_done(raw spki) || kl < 2 { ret false; }
    var kb: *u8 = cast(*u8) kv;
    if kb[0] != 0 { ret false; }
    var alg: Der = Der { p: cast(*u8) av, len: alen, pos: 0 };
    var ao: rawptr = null; var aol: i64 = 0;
    if !der_next(raw alg, 6, raw ao, raw aol) { ret false; }
    var aop: *u8 = cast(*u8) ao;
    if x509_eq(aop, aol, "2a864886f70d010101") {
        c.key_type = 1;
        var rk: Der = Der { p: kb + 1, len: kl - 1, pos: 0 };
        var rv: rawptr = null; var rl: i64 = 0;
        if !der_next(raw rk, 48, raw rv, raw rl) || !der_done(raw rk) { ret false; }
        var rs: Der = Der { p: cast(*u8) rv, len: rl, pos: 0 };
        var nv: rawptr = null; var nl: i64 = 0;
        var ev: rawptr = null; var el: i64 = 0;
        if !der_next(raw rs, 2, raw nv, raw nl) || !der_next(raw rs, 2, raw ev, raw el) || !der_done(raw rs) { ret false; }
        var np: rawptr = null; var npl: i64 = 0;
        var ep: rawptr = null; var epl: i64 = 0;
        if !der_uint(cast(*u8) nv, nl, raw np, raw npl) || !der_uint(cast(*u8) ev, el, raw ep, raw epl) { ret false; }
        c.key1 = cast(*u8) np; c.key1len = npl;
        c.key2 = cast(*u8) ep; c.key2len = epl;
    } else if x509_eq(aop, aol, "2a8648ce3d0201") {
        c.key_type = 2;
        var cvv: rawptr = null; var cvl: i64 = 0;
        if !der_next(raw alg, 6, raw cvv, raw cvl) { ret false; }
        var cvp: *u8 = cast(*u8) cvv;
        if x509_eq(cvp, cvl, "2a8648ce3d030107") { c.curve = 1; }
        else if x509_eq(cvp, cvl, "2b81040022") { c.curve = 2; }
        else { ret false; }
        c.key1 = kb + 1;
        c.key1len = kl - 1;
    } else { ret false; }
    // optional issuerUniqueID / subjectUniqueID, then extensions [3]
    while !der_done(raw tbs) {
        var t: i64 = der_peek(raw tbs);
        if t == 161 || t == 162 {
            if !der_next_any(raw tbs, raw tag, raw tv, raw tl, raw all, raw al) { ret false; }
        } else if t == 163 {
            var ev2: rawptr = null; var el2: i64 = 0;
            if !der_next(raw tbs, 163, raw ev2, raw el2) { ret false; }
            var ew: Der = Der { p: cast(*u8) ev2, len: el2, pos: 0 };
            var sv: rawptr = null; var sl: i64 = 0;
            if !der_next(raw ew, 48, raw sv, raw sl) || !der_done(raw ew) { ret false; }
            if !x509_parse_extensions(c, cast(*u8) sv, sl) { ret false; }
        } else { ret false; }
    }
    ret true;
}

// ---------------------------------------------------------------- signatures

// Verifies `sig` over `msg` with the certificate's public key.  `scheme` is
// 1 (RSA PKCS#1 v1.5) or 2 (ECDSA, DER signature); `alg` is the hash.
@trusted fn x509_verify_with_key(key: *Cert, scheme: i64, alg: i64, msg: *u8, msglen: i64, sig: *u8, siglen: i64) -> bool {
    var hs: i64 = hash_size(alg);
    if hs == 0 { ret false; }
    var dg: *u8 = heap_alloc(hs);
    hash_digest(alg, msg, msglen, dg);
    var ok: bool = false;
    if scheme == 1 && key.key_type == 1 {
        ok = rsa_verify_pkcs1(key.key1, key.key1len, key.key2, key.key2len, alg, dg, sig, siglen);
    } else if scheme == 2 && key.key_type == 2 {
        ok = ecdsa_verify_der(key.curve, key.key1, key.key1len, dg, hs, sig, siglen);
    }
    heap_free(dg);
    ret ok;
}

fn x509_check_signature(c: *Cert, issuer: *Cert) -> bool {
    ret x509_verify_with_key(issuer, c.sig_scheme, c.sig_hash, c.tbs, c.tbslen, c.sig, c.siglen);
}

// ---------------------------------------------------------------- host names

fn x509_lower(c: u8) -> u8 {
    if c >= 65 && c <= 90 { ret c + 32; }
    ret c;
}

@trusted fn x509_parse_ipv4(s: *u8, out: *u8) -> bool {
    var i: i64 = 0;
    var part: i64 = 0;
    var val: i64 = 0;
    var digits: i64 = 0;
    while s[i] != 0 {
        var ch: i64 = cast(i64) s[i];
        if ch >= 48 && ch <= 57 {
            val = val * 10 + (ch - 48);
            digits = digits + 1;
            if val > 255 || digits > 3 { ret false; }
        } else if ch == 46 {
            if digits == 0 || part >= 3 { ret false; }
            out[part] = cast(u8) val;
            part = part + 1; val = 0; digits = 0;
        } else { ret false; }
        i = i + 1;
    }
    if digits == 0 || part != 3 { ret false; }
    out[3] = cast(u8) val;
    ret true;
}

// Matches a dNSName pattern against a host (case-insensitive; a '*' is only
// accepted as the whole left-most label and covers exactly one label).
@trusted fn x509_dns_match(pat: *u8, plen: i64, host: *u8) -> bool {
    var hlen: i64 = 0;
    while host[hlen] != 0 { hlen = hlen + 1; }
    if plen < 1 || hlen < 1 { ret false; }
    if pat[plen - 1] == 46 { plen = plen - 1; }
    if host[hlen - 1] == 46 { hlen = hlen - 1; }
    var pi: i64 = 0;
    var hi: i64 = 0;
    if plen >= 2 && pat[0] == 42 && pat[1] == 46 {
        // need at least two more labels in the pattern ("*.com" is refused)
        var dots: i64 = 0;
        var k: i64 = 2;
        while k < plen { if pat[k] == 46 { dots = dots + 1; } k = k + 1; }
        if dots < 1 { ret false; }
        // skip one non-empty label of the host
        while hi < hlen && host[hi] != 46 { hi = hi + 1; }
        if hi == 0 || hi >= hlen { ret false; }
        pi = 1;
    }
    if plen - pi != hlen - hi { ret false; }
    while pi < plen {
        if x509_lower(pat[pi]) != x509_lower(host[hi]) { ret false; }
        pi = pi + 1;
        hi = hi + 1;
    }
    ret true;
}

@trusted fn x509_host_match(c: *Cert, host: *u8) -> bool {
    if c.san == null { ret false; }
    var ip: *u8 = heap_alloc(4);
    var is_ip: bool = x509_parse_ipv4(host, ip);
    var names: Der = Der { p: c.san, len: c.sanlen, pos: 0 };
    var found: bool = false;
    while !der_done(raw names) {
        var tag: i64 = 0; var v: rawptr = null; var l: i64 = 0; var all: rawptr = null; var al: i64 = 0;
        if !der_next_any(raw names, raw tag, raw v, raw l, raw all, raw al) { heap_free(ip); ret false; }
        if tag == 130 && !is_ip {
            if x509_dns_match(cast(*u8) v, l, host) { found = true; }
        } else if tag == 135 && is_ip {
            if l == 4 && raw_compare(cast(*u8) v, ip, 4) == 0 { found = true; }
        }
    }
    heap_free(ip);
    ret found;
}

// ---------------------------------------------------------------- trust store

@trusted fn x509_pem_find(buf: *u8, len: i64, from: i64, needle: *u8) -> i64 {
    var nl: i64 = 0;
    while needle[nl] != 0 { nl = nl + 1; }
    var i: i64 = from;
    while i + nl <= len {
        if buf[i] == needle[0] && raw_compare(buf + i, needle, nl) == 0 { ret i; }
        i = i + 1;
    }
    ret -1;
}

// Appends every certificate found in a PEM buffer to `out` (a VecPtr of *Cert).
// Returns how many were added.
@trusted fn x509_load_pem(buf: *u8, len: i64, out: *VecPtr) -> i64 {
    var added: i64 = 0;
    var pos: i64 = 0;
    var dbuf: *u8 = heap_alloc(len / 4 * 3 + 8);
    while pos < len {
        var b: i64 = x509_pem_find(buf, len, pos, "-----BEGIN CERTIFICATE-----");
        if b < 0 { pos = len; }
        else {
            var start: i64 = b + 27;
            var e: i64 = x509_pem_find(buf, len, start, "-----END CERTIFICATE-----");
            if e < 0 { pos = len; }
            else {
                var n: i64 = base64_decode(buf + start, e - start, dbuf);
                if n > 0 {
                    var c: ^Cert = x509_parse(dbuf, n);
                    if c != null { vec_ptr_push(out, cast(rawptr) c); added = added + 1; }
                }
                pos = e + 25;
            }
        }
    }
    heap_free(dbuf);
    ret added;
}

fn x509_load_pem_file(path: *u8, out: *VecPtr) -> i64 {
    if file_exists(path) == 0 { ret 0; }
    var s: ^String = read_to_string(path);
    if s == null { ret 0; }
    var added: i64 = x509_load_pem(s.data, s.len, out);
    string_free(s);
    ret added;
}

// Windows keeps its trust anchors in the certificate store (no-op elsewhere).
@trusted fn x509_load_store_roots(out: *VecPtr) -> i64 {
    var added: i64 = 0;
    var ctx: i64 = 0;
    var der: i64 = 0;
    var len: i64 = 0;
    var more: bool = true;
    while more {
        ctx = sys_root_next(ctx, raw der, raw len);
        if ctx == 0 {
            more = false;
        } else {
            var c: ^Cert = x509_parse(cast(*u8) der, len);
            if c != null { vec_ptr_push(out, cast(rawptr) c); added = added + 1; }
        }
    }
    ret added;
}

// Loads the system trust store from the usual bundle locations.
@trusted fn x509_load_system_roots(out: *VecPtr) -> i64 {
    var n: i64 = 0;
    // like curl: SSL_CERT_FILE names a bundle to trust (used by proxies that re-sign traffic)
    var custom: *u8 = env_get("SSL_CERT_FILE");
    if custom != null && custom[0] != 0 { n = x509_load_pem_file(custom, out); }
    if n == 0 { n = x509_load_pem_file("/etc/ssl/certs/ca-certificates.crt", out); }
    if n == 0 { n = x509_load_pem_file("/etc/pki/tls/certs/ca-bundle.crt", out); }
    if n == 0 { n = x509_load_pem_file("/etc/ssl/cert.pem", out); }
    if n == 0 { n = x509_load_pem_file("/etc/ssl/ca-bundle.pem", out); }
    if n == 0 { n = x509_load_store_roots(out); }
    ret n;
}

// ---------------------------------------------------------------- chain

fn x509_valid_at(c: *Cert, now: i64) -> bool { ret now >= c.not_before && now <= c.not_after; }

fn x509_can_sign(c: *Cert) -> bool {
    if c.has_bc == 0 || c.is_ca == 0 { ret false; }
    if c.has_ku == 1 && (c.ku & 4) == 0 { ret false; }
    ret true;
}

fn x509_same_name(a: *Cert, b: *Cert) -> bool {
    ret x509_bytes_eq(a.subject, a.subjectlen, b.issuer, b.issuerlen);
}

// Checks `chain` (leaf first; a VecPtr of *Cert as sent by the server)
// against `anchors`, for `host` (null skips the name check) at Unix time `now`.
// Returns X509_OK or an X509_E_* code.
fn x509_verify_chain(chain: *VecPtr, anchors: *VecPtr, host: *u8, now: i64) -> i64 {
    var n: i64 = vec_ptr_len(chain);
    if n < 1 { ret 1; }
    var leaf: *Cert = vec_ptr_get(chain, 0);
    if host != null && !x509_host_match(leaf, host) { ret 6; }
    if leaf.has_eku == 1 && leaf.eku_ok == 0 { ret 9; }
    var i: i64 = 0;
    while i < n {
        var c: *Cert = vec_ptr_get(chain, i);
        if !x509_valid_at(c, now) { ret 2; }
        i = i + 1;
    }
    i = 0;
    while i + 1 < n {
        var c: *Cert = vec_ptr_get(chain, i);
        var p: *Cert = vec_ptr_get(chain, i + 1);
        if !x509_same_name(p, c) { ret 4; }
        if !x509_can_sign(p) { ret 7; }
        if p.pathlen >= 0 && i > p.pathlen { ret 8; }
        if !x509_check_signature(c, p) { ret 3; }
        i = i + 1;
    }
    var top: *Cert = vec_ptr_get(chain, n - 1);
    var result: i64 = 5;
    var k: i64 = 0;
    var na: i64 = vec_ptr_len(anchors);
    while k < na && result != 0 {
        var a: *Cert = vec_ptr_get(anchors, k);
        if x509_bytes_eq(a.der, a.derlen, top.der, top.derlen) {
            result = 0;
        } else if x509_same_name(a, top) && x509_valid_at(a, now) && x509_can_sign(a) {
            if a.pathlen >= 0 && (n - 1) > a.pathlen { result = 8; }
            else if x509_check_signature(top, a) { result = 0; }
            else { result = 3; }
        }
        k = k + 1;
    }
    ret result;
}
